programs.sol:
"""Programming-construct words produce negative activations.

The central cues are command, function, field, method, and parameter.  Their
response grows with recent programming vocabulary, code-like punctuation,
source-file suffixes, message markers, and backticks.  More general data/interface nouns have weaker responses.  Context
is a decaying count, reset at document boundaries; only past tokens are used.
Identifier pieces, plurals, abbreviations, and some translated terms are
recognized explicitly. Unrecognized tokens predict zero; weak miscellaneous
responses are deliberately left unexplained.
"""

import re

READS = ()

# Baseline strength and additional strength in programming context.
CORE = {
    'command': (1.1, 0.4),
    'function': (0.6, 0.45),
    'field': (0.45, 1.5),
    'method': (0.3, 0.95),
    'parameter': (0.55, 1.0),
    'variable': (0.35, 1.05),
    'property': (0.2, 0.8),
    'argument': (0.6, 0.45),
    'attribute': (0.75, 0.2),
    'array': (0.35, 0.3),
    'flag': (0.6, 0.4),
}
# In names/identifiers, these noun pieces have relatively stable strengths.
IDENTIFIERS = {
    'command': 1.1,
    'function': 0.9,
    'field': 1.05,
    'method': 0.85,
    'parameter': 0.75,
    'variable': 0.65,
    'property': 0.6,
    'attribute': 0.5,
    'array': 0.3,
    'value': 0.3,
    'class': 0.4,
    'interface': 0.45,
    'element': 0.4,
}
MEDIUM = set('''column flag module option script button header callback
instruction directive macro'''.split())
LIGHT = set('''class dict dictionary element interface object operation rule
statement struct table tool value feature'''.split())
CODE_WORDS = set('''python javascript typescript golang java bash shell code
programming software compiler api sql json yaml xml html cli github git npm
pip pytest import def const var return null true false argv args cmd printf
sudo grep workspace testbed repository traceback func'''.split())
CODE_SIGNS = (';', '=>', '::', '==', '/*', '//', '&&', '.py', '.go', '.js',
              '/workspace', '/testbed', '__', '<tool_', '<|im_')
ORDINARY = set('''electric magnetic playing battle cost bodily mitochondrial
endothelial swallowing funding intellectual agricultural'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        context, previous = 0.0, ''
    else:
        _, context, previous = carry
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.strip('_-.(/\\:')
    word = re.sub(r'^(get|set)(?=[A-Z])', '', word)
    word = re.sub(r'(?<=.)(Name|Type|Id)$', '', word)
    identifier = ((raw != word or word[:1].isupper())
                  and not token.startswith(' '))
    word = word.lower()
    plural = word.endswith('s') and word != 'class'
    if word.endswith('ies'):
        word = word[:-3] + 'y'
    elif plural:
        word = word[:-1]
    code = min(context / 3.0, 1.0)
    if word in CORE:
        base, extra = CORE[word]
    elif word in MEDIUM:
        base, extra = 0.4, 0.2
    elif word in LIGHT:
        base, extra = 0.15, 0.25
    else:
        base, extra = 0.0, 0.0
    strength = base + extra * code
    if strength:
        if identifier and word in IDENTIFIERS:
            strength = IDENTIFIERS[word]
        if plural:
            if word in {'function', 'method'} and not identifier:
                strength = 0.65 * base + extra * code
            else:
                strength *= (0.95 if word in {'command', 'field', 'argument'}
                             else 0.55)
        if '`' in previous[-3:]:
            strength += 0.5 if word in CORE else 0.15
        if previous.strip().lower() in ORDINARY:
            strength *= 0.25
        if (word == 'field' and raw[:1].islower()
                and not token[:1].isspace() and previous[-1:].isalpha()):
            strength = 0.15
    if word == 'module' and plural:
        strength = 0.0 if identifier else 0.15
    if token == 'arguments':
        strength = 1.02
    elif token == 'command':
        strength = 1.0
    elif raw.lower() in {'cmd', 'func'}:
        strength = 0.65
    elif raw.lower() in {'arg', 'args', 'params'}:
        strength = 0.3
    elif raw == 'API':
        strength = 0.35
    elif raw == '.go':
        strength = 0.9
    elif raw == '.py':
        strength = 0.18
    # Translated constructs; �数 can be a byte-fragment suffix of 函数.
    elif raw in {'函数', '�数', '命令', '字段', '变量', '변수'}:
        strength = 1.2
    elif raw in {'功能', '方法', '值', '类'}:
        strength = 0.3 + 0.4 * code
    elif raw == '参数':
        strength = 0.65
    elif raw == '属性':
        strength = 0.75
    elif word in {'função', 'función', 'fonction', 'funktion', '함수', '関数'}:
        strength = 0.8
    elif word.startswith(('функци', 'команд')):
        strength = 0.8
    elif raw == '令':
        strength = 0.9
    signal = float(raw.lower() in CODE_WORDS)
    if any(mark in token for mark in CODE_SIGNS):
        signal += 0.8
    if '`' in token:
        signal += 0.4
    context = min(9.0, 0.97 * context + signal)
    return (doc, context, token), -float(strength)

programs.haiku:
"""Software-jargon detector: negative on words for code and API parts.

Layer-0 MLP component layers.0.mlp.down_proj:5632 writes a negative signal when the current
token is a word for a piece of software: "command", "function", "field", "argument",
"parameter", "attribute", "flag" are strongest; "method", "variable", "module", "option",
"column", "array" are medium; "value", "property", "table", "rule" are weak. The same words
are near 0 in ordinary English ("electric field", "military command"), so each value is
scaled by how code-like the preceding 24 tokens are (markup, brackets, identifiers, other
code words). Everything else predicts 0.
"""

READS = ()

STRONG = {"command", "function", "field", "argument", "parameter", "attribute", "flag", "func",
          "cmd", "instruction"}
MEDIUM = {"variable", "module", "option", "column", "method", "array", "macro", "script",
          "button", "callback", "struct", "tool", "header", "folder"}
WEAK = {"value", "property", "table", "rule", "arg", "args", "params", "element", "feature",
        "vars", "operation", "object", "class"}
CODE_MARK = ("(", ")", "[", "]", "{", "}", "<", ">", ";", "=", "_", "/", "\\", "`", "#", '"')


def _word(token):
    return token.strip().lower().lstrip("._-(/").rstrip("_")


def _tier(word):
    if word in STRONG:
        return -1.0
    if word in MEDIUM:
        return -0.5
    if word in WEAK:
        return -0.25
    if word.endswith("s"):
        return _tier(word[:-1]) if word[:-1] in STRONG | MEDIUM | WEAK else 0.0
    return 0.0


def _codey(token):
    """A token that looks like code: markup, identifiers, or a programming word."""
    if any(mark in token for mark in CODE_MARK) or "." in token.strip(".") or "\n" in token:
        return True
    return _tier(_word(token)) != 0.0


def step(carry, prefix, upstream):
    value = _tier(_word(prefix.token_strings[-1]))
    if value == 0.0:
        return carry, 0.0
    recent = prefix.token_strings[-25:-1]
    code_share = sum(_codey(tok) for tok in recent) / max(1, len(recent))
    return carry, value * (0.5 + code_share)

programs.luna:
"""Predict sparse negative activations on software commands, API arguments,
code structures, and interface/data terms. Other words receive zero.
"""
READS = ()

CALL_WORDS = {
    "command", "commands", "argument", "arguments", "parameter", "parameters",
    "function", "functions", "func", "method", "methods", "param",
    "函数", "令",
}
STRUCTURE_WORDS = {
    "macro", "trait", "module", "script", "operation", "interpreter",
}
OBJECT_WORDS = {
    "option", "options", "button", "field", "fields", "value", "values",
    "array", "arrays", "table", "tables", "column", "columns", "variable",
    "variables", "callback", "callbacks", "element", "elements", "tool",
    "tools", "rule", "rules", "page", "listener", "header", "headers",
    "dictionary", "key", "property", "properties", "attribute",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].casefold().strip()
    if raw.endswith(".go"):
        return None, -0.75
    word = raw.strip(" \t\r\n.,:;!?()[]{}<>\"'`_-/\\")
    if word in CALL_WORDS:
        return None, -0.85
    if word in STRUCTURE_WORDS:
        return None, -0.65
    if word in OBJECT_WORDS:
        return None, -0.45
    return None, 0.0

programs.sol:
"""Approximate the component's strongest harvested pattern: per-word completion.

A word split after 'per' produces a positive response, especially perched,
peruse and perils. Different word families have different strengths. There
is also a smaller response to the split endings '-ched' and '-use'. The
Latin phrase 'per se' is treated separately. Other activity is left at zero;
this is not a model of the many small, word-specific background responses.
"""
import re

READS = ()
PER_FRAGMENT = re.compile(r'(?:^|[\W_])per$', re.IGNORECASE)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0

    # The spelling endings can respond even with another word beginning.
    if previous[-1:].isalpha():
        if token == 'ched':
            value = 0.15
        elif token == 'use':
            value = 0.18

    if PER_FRAGMENT.search(previous.strip()):
        if token and token[0].isalpha():
            value = 0.07
            # Perch and peruse, including their inflected forms.
            if token == 'ched':
                value = 0.63
            elif token in {'use', 'using', 'used'}:
                value = 0.60
            elif token == 'usal':
                value = 0.48
            # Peril and perception; smaller percentage/perversion responses.
            elif token in {'ils', 'cepts'}:
                value = 0.56
            elif token == 'ceived':
                value = 0.50
            elif token == 'ceiving':
                value = 0.38
            elif token in {'il', 'ception', 'ceptions', 'ce', 'cents', 'verted'}:
                value = 0.27
            elif token in {'fection', 'imeters'}:
                value = 0.35
        elif token.lower() == ' se':
            value = 0.26
    return (doc, token), value

"""An ENS spelling feature, with weaker sense/intensity and focus responses.

Short ENS pieces are strongest. Complete words in the density, intensity,
tension and sensation families are weaker. Listed plural and verb endings
are weaker still, as are fragments following i or y. Some Chinese sensing,
concentration and assurance words are recognized too. The carry tracks the
unfinished word and last prediction for inflections and quantity + "of"
phrases. It resets at document boundaries.
"""
import re

READS = ()
INFLECTIONS = {
    'antig', 'allerg', 'chick', 'que', 'happ', 'op', 'citiz', 'specim',
    'broad', 'hard', 'weak', 'wid', 'short', 'length', 'soft', 'dark',
    'deep', 'wors', 'bright', 'strength',
}
ROOTS = {'dens': 1.9, 'intens': 2.0, 'tens': 1.6, 'sens': 1.2}
QUANTITIES = {'tens', 'hundreds', 'thousands', 'dozens'}


def response(token, word):
    s = token.strip().lstrip('_-./("').lower()
    if s == 'ens':
        if word.lower() in INFLECTIONS:
            return -1.65
        return -3.2 if word.lower().endswith(('i', 'y')) else -4.5
    for root, strength in ROOTS.items():
        if s.startswith(root):
            if s == root:
                return -4.6 if root == 'tens' else -3.75
            if s.startswith('sensib'):
                return -2.4
            short = len(s) == len(root) + 1 and root != 'intens'
            return -strength - (0.5 if short else 0.0)
    if s.startswith('lens'):
        return -2.4 if s == 'lens' else -1.9
    if s.endswith('ens') and len(s) <= 4:
        return -2.7
    if s.startswith('ensur'):
        return -1.25
    if s.startswith('ens'):
        return -3.3 if len(s) <= 4 else -1.7
    if s.startswith(('defens', 'extensiv', 'suspens', 'consens', 'cens')):
        return -0.75
    if 'ens' in s:
        return -0.15
    if s in {'ns', 'dns'}:
        return -1.65
    if s == 'den':
        return -0.85
    if s in {'ans', 'ins', 'ons', 'cons', 'enc', 'ence', 'enz', 'env'}:
        return -0.5
    if s.startswith('focus'):
        return -1.05
    if s in QUANTITIES | {'millions', 'billions'}:
        return -1.45 if s == 'hundreds' else -0.65
    if s in {'感', '敏感', '敏', '传感器', '密集', '凝', '紧张', '紧凑'}:
        return -1.4
    if s in {'保', '确保', '確保'}:
        return -0.95
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, previous = carry[1:] if carry and carry[0] == doc else ('', 0.0)
    token = prefix.token_strings[-1]
    old_word = word.lower()
    if token[:1].isspace():
        word = ''
    value = response(token, word)
    if token.strip().lower() == 'of' and old_word in QUANTITIES:
        value = 0.38 * previous
    match = re.search(r'[^\W\d_]+$', token)
    fragment = match.group() if match else ''
    word = word + fragment if fragment == token else fragment
    return (doc, word[-32:], value), value

"""Predict zero or negative activation from pronunciation and transliteration spelling.

The main cues are marked Latin vowels, IPA characters, and pinyin-like initials,
medials, and endings. Nasal codas after tone-marked vowels are especially strong.
Nearby CJK ideographs, Chinese surname pairs, and pronunciation labels provide
context. Explicit labels persist for 64 tokens; clear phonetic marks for 16.
All state resets at a document boundary. This approximates the rare strong
negative pattern, not the component's positive or weak lexical variation.
"""
import unicodedata as ud
import re
from functools import lru_cache

READS = ()
INITIALS = set('b p m f d t n l g k h j q x zh ch sh r z c s y w'.split())
LONGEST_INITIALS = tuple(sorted(INITIALS, key=len, reverse=True))
RETROFLEX = {'zh', 'ch', 'sh'}
PALATAL = {'j', 'q', 'x'}
FINALS = set('a o e ai ei ao ou an en ang eng ong i ia ie iao iu ian in '
             'iang ing iong u ua uo uai ui uan un uang ueng v ve van vn'.split())
NASAL_RIMES = {'eng', 'iang', 'iong', 'uang'}
SURNAMES = set('Wang Li Zhang Liu Chen Yang Huang Zhao Zhou Wu Xu Sun Zhu Ma '
               'Hu Guo He Gao Lin Luo Zheng Liang Xie Song Tang Han Feng Yu '
               'Deng Cao Peng Xiao Tian Dong Yuan Pan Cai Jiang Shi Wei Jin '
               'Lu Du Ding Shen Qin Yao Kong Bai Cui Zhong Fang Gu Qian Hou '
               'Lei Meng Long Wan Tan Niu Xiong Shao'.split())


@lru_cache(maxsize=32768)
def spelling(s):
    w = s.strip()
    d = ud.normalize('NFD', w)
    plain = ''.join(c for c in d if not ud.category(c).startswith('M')).lower()
    latin = bool(w) and all('LATIN' in ud.name(c, '') for c in w)
    vowel = latin and any(ord(c) > 127 for c in w) and plain in set('aeiouy')
    macron, caron = '\u0304' in d, '\u030c' in d
    tone = any(c in d for c in '\u0300\u0301\u0304\u030c')
    chinese = any('\u3400' <= c <= '\u9fff' for c in s)
    ipa = bool(w) and all(0x250 <= ord(c) <= 0x2af or c in 'ːˈˌʰʷ' for c in w)
    return w, plain, vowel, macron, caron, tone, chinese, ipa


def rime_response(initial, rime):
    """More distinctive Chinese syllable combinations get stronger responses."""
    if initial not in INITIALS:
        return 0.0
    if rime == 'eng':
        return -.70 if initial in RETROFLEX else -.22
    if rime == 'iang':
        return -.65 if initial in PALATAL else -.24
    if rime == 'ian' and initial in PALATAL:
        return -.30
    if rime == 'ong':
        return -.33 if initial in RETROFLEX else -.18
    if rime == 'ui':
        return -.40 if initial in RETROFLEX else -.09
    if rime in {'uan', 'uang'}:
        return -.20
    if rime in {'ang', 'ao'} and initial in RETROFLEX:
        return -.24
    return 0.0


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous, chinese_left, marks_left, phonetic_left = '', 0, 0, 0
    if carry is not None and carry[0] == doc:
        _, previous, chinese_left, marks_left, phonetic_left = carry
    w, plain, vowel, macron, caron, tone, chinese, ipa = spelling(s)
    pw, pp, pvowel, pmacron, pcaron, ptone, _, _ = spelling(previous)
    value = 0.0
    if vowel:
        if macron:
            value -= .18 + .25 * (pp in INITIALS)
        elif caron:
            value -= .06 if plain == 'e' else .87
        value -= .05 * (pp in INITIALS) + .34 * (pp in RETROFLEX)
        value -= .50 * (chinese_left > 0) + .06 * (marks_left > 0)
    if tone and not vowel and plain in FINALS:
        value -= .15 * (pp in INITIALS) + .35 * (pp in RETROFLEX)
        value -= .50 * (chinese_left > 0)
    # Explicit pronunciation labels disambiguate acute/grave tone marks.
    if tone and not (macron or caron) and (vowel or plain in FINALS):
        if phonetic_left > 0:
            value -= .9 if phonetic_left > 24 else .5
    if vowel and macron and pp == 'y':
        value -= .4
    if ipa:
        value -= .37 if w == 'ə' else .06
    if s == w:
        # A preceding fragment can contain an initial plus an i/u medial.
        match = re.search(r'(zh|ch|sh|[bpmfdtnlgkhjqxrzcsyw])([iu]?)$', pp)
        if match:
            initial, medial = match.groups()
            value += rime_response(initial, medial + w)
        if s == 'ng' and pvowel and ptone:
            value -= 1.05
        if s == 'n' and pvowel and (pmacron or (pcaron and pp != 'e')):
            value -= .50
        if s in {'i', 'u', 'o', 'y'} and pvowel and ptone:
            if chinese_left > 0 or phonetic_left > 0:
                value -= .60
    is_syllable = plain in FINALS
    if w.isascii() and w.isalpha() and len(w) > 1:
        for initial in LONGEST_INITIALS:
            if plain.startswith(initial):
                rime = plain[len(initial):]
                is_syllable = rime in FINALS
                if rime in NASAL_RIMES:
                    scale = .4 if rime == 'eng' else .8
                    value += scale * rime_response(initial, rime)
                elif initial in PALATAL and rime in {'ian', 'ing'}:
                    value -= .20
                break
    if w.isascii() and w.isalpha() and is_syllable and chinese_left > 0:
        value -= .15
    if s.startswith(' ') and w in SURNAMES:
        value -= .26 * (chinese_left > 0) + .21 * (pw in SURNAMES)
    if w in {'.cn', '-CN'}:
        value -= .18 if w == '.cn' else .45
    if w == 'inyin' and pp == 'p':
        value -= .78
    chinese_left = 12 if chinese else max(0, chinese_left - 1)
    marked = macron or (caron and plain != 'e') or ipa
    marks_left = 12 if marked else max(0, marks_left - 1)
    label = (pw + w).lower()
    explicit = w.lower() in {'pinyin', 'ipa', 'pronounced', 'romanized'}
    explicit = explicit or label in {'pinyin', 'romanized', 'pronounced'}
    nasal_tone = s == 'ng' and pvowel and ptone
    phonetic_left = max(0, phonetic_left - 1, 64 if explicit else 0,
                        16 if (vowel and (macron or (caron and plain != 'e')))
                        or ipa or nasal_tone else 0)
    return (doc, s, chinese_left, marks_left, phonetic_left), float(value)

"""Recognize 'there', with weaker 'it' and 'here' signals.

'There' is strongly negative after clause introducers, less negative after
'be' or spatial words. Case, spacing, and attached punctuation also matter.
Capitalized 'It' is negative; lowercase 'it' follows a few grammatical cues,
including a small positive response after 'make'. Spaced 'here' is positive.
All other tokens are zero. Context never crosses a document boundary.
"""
READS = ()

CONDITIONS = {'if', 'unless', 'until', 'though', 'whether', 'although'}
CLAUSES = {'that', 'because', 'since', 'where', 'when', 'while'}
COORDINATORS = {'and', 'or', 'but', 'so', 'then', 'therefore'}
THOUGHT_AND_ASSERTION = {
    'say', 'says', 'said', 'think', 'thinks', 'thought', 'know', 'knows',
    'knew', 'believe', 'believes', 'believed', 'suppose', 'means', 'sure',
}
BE_PRESENT = {'is', 'are'}
BE_PAST = {'was', 'were', 'been'}
PATH_WORDS = {'get', 'got', 'getting', 'go', 'going', 'come', 'came', 'in', 'down'}
UNCERTAIN = {'maybe', 'perhaps'}
INTRODUCERS = CONDITIONS | CLAUSES | COORDINATORS
OTHER_CONTEXT = -5.35


def there_after(word):
    if word in BE_PRESENT or word == 'out':
        return -2.3
    if word in BE_PAST:
        return -2.9
    if word in {'be', 'being', 'from', 'over', 'not'}:
        return -3.5
    if word in PATH_WORDS:
        return -4.0
    if word in {'up', 'back', 'still', 'already', 'right'}:
        return -4.4
    if word == 'when':
        return -8.2
    if word in {'that', 'because', 'since'}:
        return -7.7
    if word in {'if', 'unless', 'until', 'though', 'where', 'while'}:
        return -7.4
    if word in {'whether', 'although', 'but', 'so', 'then', 'therefore'}:
        return -7.0
    if word in {'and', 'or', 'which', 'why'} or word in THOUGHT_AND_ASSERTION:
        return -6.6
    if word in {'as', 'like'}:
        return -6.0
    if word in UNCERTAIN:
        return -5.8
    return OTHER_CONTEXT


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        before = prefix.token_strings[-2]
    previous = before.strip().lstrip('"“')
    prev = previous.lower()
    raw = token.strip()
    word = raw.lstrip('."“')
    spaced = token.startswith((' ', '\t'))
    value = 0.0
    if word.lower() == 'there':
        if word != raw:
            value = -5.0
        elif word.isupper():
            value = -4.8
        elif not spaced:
            value = -6.6 if word[0].isupper() else -5.1
        else:
            value = there_after(prev)
            if prev in INTRODUCERS and previous[:1].isupper():
                value -= 0.4
            if previous in {',', ';', ':', '.', '–', '—', '-'}:
                value = -6.7
            if word == 'There' and value == OTHER_CONTEXT:
                value = -6.0 if previous and not previous.isspace() else -6.5
            if word == 'There' and previous == '.':
                value = -7.25
    elif word.lower() == 'it':
        if word[0].isupper() and not word.isupper():
            value = -0.6
        elif spaced and word == 'it':
            if prev in {'make', 'makes', 'making', 'made'}:
                value = 0.25
            elif prev in {'because', 'since', 'but'}:
                value = -0.45
            elif prev in INTRODUCERS or previous in {',', ';', ':'}:
                value = -0.3
            else:
                value = -0.06
    elif word == 'here' and spaced:
        value = 0.33
    return None, value

programs.luna:
"""Use punctuation-trimmed current words as cues for negative activation."""
import unicodedata

READS = ()


def bare_word(token):
    token = token.strip()
    while token and unicodedata.category(token[0]).startswith("P"):
        token = token[1:]
    while token and unicodedata.category(token[-1]).startswith("P"):
        token = token[:-1]
    return token


def step(carry, prefix, upstream):
    current = bare_word(prefix.token_strings[-1])
    if current == "there":
        return None, -6.15
    if current == "There":
        return None, -6.75
    if current == "It":
        return None, -0.61
    if current == "it":
        return None, -0.26
