GROUPS = {
    's': 'sſśšșşсшщσςسشス斯스สस',
    'h': 'hх', 'l': 'lлλł', 'u': 'uуυ', 'z': 'zзζżźž',
    'v': 'vв', 'r': 'rрρ', 'd': 'dдδ',
}
CANONICAL_LETTERS = {c: letter for letter, chars in GROUPS.items() for c in chars}
INITIAL = {
    's': -2.0, 'd': -.2, 'h': 1.8, 'l': 1.0,
    'u': .7, 'v': .4, 'r': .35, 'w': .7, 'y': .7, 'z': 1.1,
}


@lru_cache(maxsize=8192)
def spelling(token):
    return ''.join(CANONICAL_LETTERS.get(c, c) for c in token.lower())


# Dependent u/uu and related vowel signs in Devanagari and Thai.
VOWEL_SIGNS = frozenset('ुूัิีึืุู')


def continuation_value(text):
    if text in ("'s", '’s'):       # Possessive/clitic s
        return -1.9
    if text.strip() == 's' and text[0].isspace():
        return -.65              # A separate, space-prefixed letter s
    if not text or text[0].isspace():
        return 0.0
    first = text[0]
    if first in VOWEL_SIGNS:
        value = .9
    elif first.isalpha():
        value = INITIAL.get(first, .15)
    elif first.isdigit():
        value = .4
    elif 's' in text[:3]:
        value = -.44
    else:
        return 0.0
    value -= .45 * sum(.5 ** (j - 1) for j, c in enumerate(text)
                       if j > 0 and c == 's')
    value -= .2 * (len(text) == 1)
    return value / (1 + .5 * max(0, len(text) - 2))


