    if root in {'tell', 'show', 'provide'} and word in {'me', 'you', 'us'}:
        return state, -0.45 if word == 'you' else -1.20
    if root == 'do' and word in {'you', 'this'}:
        return state, 0.22 if word == 'you' else 0.80
    if root in {'let', 'help'} and word in {'me', 'us'}:
        return state, -0.03 if root == 'let' else 0.08
    if word == 'you' and p in MODALS | {'if', 'then'}:
        return state, -0.20
    if prev == 'In' and word == 'this':
