"""Object pronouns and determiners that follow a verb or a preposition.

Component layers.0.mlp.down_proj:5645 fires on a pronoun or determiner that is the
object of the word before it, as in "...find [it]", "...keep [this] listing",
"...make [them] ...", "...with [him]", "...prevent [this]", "...secure [your] product".
It is near zero when the same word opens a clause ("so [it] works", "if [this] ...",
"[it] is ..."), and negative when it is the indirect object of give / tell / provide
("give [me]", "told [them]").

The rule: pronoun strength, times a factor read from the previous word.
"""

READS = ()

# Pronouns whose object use is strong; the number is how strong they are.
OBJECT_PRONOUNS = {"it": 1.0, "them": 1.0, "him": 0.8, "her": 0.8, "this": 0.6, "you": 0.6, "one": 0.6}

# Determiners and quantifier pronouns that fire about equally in every position.
ANY_POSITION = {"such", "your", "everything", "anything", "something", "nothing", "yourself"}

# Indirect objects of give-type verbs: negative.
INDIRECT = {"me", "us", "you", "them", "him", "people"}

GIVE_VERBS = set(
    "give gives gave giving given tell tells told telling provide provides provided "
    "offer offers offered show shows showed send sends sent".split()
)

PREPOSITIONS = set(
    "to for with on at from about into through under between around like by over after "
    "before during among across against without within above below toward towards upon "
    "onto via than".split()
)

VERBS = set(
    "make makes made keep keeps kept put puts bring brings brought take takes took get gets got "
    "use uses used find finds found see sees saw read reads write writes know knows knew "
    "think thinks thought believe believes want wants need needs try tries add adds call calls "
    "allow allows let lets leave leaves follow follows help helps improve change changes "
    "protect build builds run runs set sets save saves love loves watch watches explain "
    "understand understands include includes hold holds say says ask asks apply applies "
    "buy sell choose open close start stop play feel carry move fix check test remove "
    "replace update enjoy like learn teach join reach cover accept discuss post install "
    "handle convert solve compute pay increase select assume address resolve support extend "
    "face enter process affect ensure share create consider".split()
)

# Words that open a clause, or punctuation: the word after them is usually a subject.
CLAUSE_OPENERS = set(
    "so then if but and or what can because since once until now thus however maybe "
    "perhaps unless as in when while . , ! ? : ; ( ) \" ' - / = $ [ “ <s>".split()
)


def _previous_word(prefix):
    """The word before the newest token, or '' at the start of a document."""
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-2].strip().lower()


def _context_factor(prev):
    if prev in GIVE_VERBS:
        return "give"
    if prev in CLAUSE_OPENERS:
        return "clause"
    if prev in PREPOSITIONS or prev in VERBS or (len(prev) > 4 and prev.endswith(("ing", "ed"))):
        return "verb"
    return "other"


FACTOR = {"verb": 1.0, "other": 0.5, "clause": 0.12}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = _previous_word(prefix)
    context = _context_factor(prev)
    if word in ANY_POSITION:
        value = 0.9
    elif word in OBJECT_PRONOUNS:
        value = 1.5 * OBJECT_PRONOUNS[word] * FACTOR.get(context, 0.0)
    else:
        value = 0.0
    if word in INDIRECT and context == "give":
        value = -0.8
    return carry, float(value)

