TAGS = {
    '<think>': 0.164, '</think>': 0.151,
    '<tool_call>': -0.026, '</tool_call>': 0.068,
}


def activation(raw):
    if raw in TAGS:
        return TAGS[raw]
    word = raw.strip()
    s = word.lower()
    n, at = len(s), s.find('l')
    if not s.isascii() or not s.isalpha() or at < 0:
        return 0.001
    if s in ('lycer', 'ldl'):
        return -0.45
    if raw in ('lov', 'loff'):
        return -0.39
    if s == 'lex':
        return -0.34 if raw == s else -0.27
    if s == 'lr':
        return -0.53 if raw == 'LR' else -0.31
    if s.count('l') > 1 or at == n - 1:
        return 0.014
    if at >= 2:
        return 0.004
    following = s[at + 1]
    if n == 2 and at == 0:
        if following not in VOWELS:
            if following in 'wx':
                return -0.47
            return -0.17 if following in 'dtcs' else -0.33
        if following == 'u':
            return -0.06
        return -0.02 if following == 'y' else 0.03
    if at == 1 and n == 3 and following not in VOWELS:
        if following == 's':
            return -0.006
        if s[0] == 'e':
            return -0.30 if following in 'fpn' else -0.17
        if s[0] == 'i':
            if following == 'k':
                return -0.32
            return -0.18 if following == 'm' else -0.055
        return -0.08
    if at == 0:
        if raw[0].isspace() or word[0].isupper():
            return -0.012
        if n == 3 and s[1] in 'auy':
            return -0.16
        return -0.055
    return -0.02


def step(carry, prefix, upstream):
    if (len(prefix.document_ids) == 1
            or prefix.document_ids[-1] != prefix.document_ids[-2]):
        return None, 0.01
    return None, activation(prefix.token_strings[-1])

