"""A local spelling response: backslashes and wordpieces following r.

A standalone backslash is positive, especially after a space or line break.
Otherwise this approximates the signed response on a word continuation after
an r-ending token (weakly after r plus one letter). Short consonant-rich
pieces are mostly positive; isolated vowels and familiar grammatical endings
are less positive or negative. Longer preceding pieces weaken the response.
The space-prefixed preposition 'of' has a small negative exception.
This is a spelling heuristic, not a grammatical or phonetic parser.
"""
import unicodedata

READS = ()
# R-like letters in several scripts, including accented and fullwidth forms.
R_LETTERS = frozenset('rрρرڕռრरਰரరರരรřŕʀｒ')
VOWELS = frozenset('aeiou')
CYRILLIC = str.maketrans('аеёиоуыэюянртбдпксмлфгзвх',
                        'aeeiouyeuanrtbdpksmlfgzvh')
# Literal spellings, not inferred grammatical roles.
INFLECTIONS = {'s': -0.11, 'es': -1.0, 'ed': -0.64, 'ing': -0.34}


def continuation(token):
    if token.lower() in INFLECTIONS:
        return INFLECTIONS[token.lower()]
    word = ''.join(c for c in unicodedata.normalize('NFKD', token.lower())
                   if not unicodedata.combining(c)).translate(CYRILLIC)
    word = word.replace('ο', 'o')  # Greek omicron.
    n, first = len(word), word[0]
    if n == 1 and first in 'aeiouy':
        if first in 'eo':
            return -0.40
        return -0.22 if first in 'iy' else 0.0
    consonants = [c.isalpha() and c not in VOWELS for c in word]
    cluster = any(a and b for a, b in zip(consonants, consonants[1:]))
    return (0.05 * min(sum(consonants), 3)
            + (0.27 if n <= 3 else 0.19) * (first == 'a')
            + 0.39 * (first == 'n')
            + 0.30 * (first in 'bpdt')
            + 0.16 * (n == 2 and word[-1] in 'bdptkg')
            + 0.09 * cluster
            - 0.13 * (n >= 5))


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, token)
    if token == ' \\':
        value = 0.80
        if not previous:
            value = 0.58
        elif previous.isspace() and len(previous) > 1:
            value = 0.70
        elif '\\' in previous:
            value = 0.58
        return carry, value
    if token == '\\':
        if not previous:
            value = 0.15
        elif '\n' in previous or previous.isspace():
            value = 0.86
        elif '$' in previous and not previous.endswith('{'):
            value = 0.82
        elif previous[-1].isdigit():
            value = 0.47
        elif previous[-1] in '()[];,:' or '\\' in previous:
            value = 0.18
        else:
            value = 0.36
        return carry, value
    previous = previous.lower()
    if previous and previous[-1] in R_LETTERS:
        proximity = 1.0
    elif (len(previous) > 1 and previous[-2] in R_LETTERS
          and previous[-1].isalpha()):
        proximity = 0.2
    else:
        return carry, 0.0
    if token == ' of':
        return carry, -0.13 * proximity
    if not token or not token[0].isalpha():
        return carry, 0.0
    strength = min(1.0, 2.5 / max(len(previous.strip()), 1)) ** 1.5
    return carry, float(proximity * strength * continuation(token))

