    (0.65, 'know knows traditional classical typically referred loved unknown'),
    (0.5, 'shown standard often common typical conventional generally '
     'attention remember recall recognize forget knowing awareness aware '
     'feared cited proven'),
    (0.4, 'considered seen thought reported established recorded usually '
     'successful characterized ever knew heard alleged studied identified '
     'favorite favourite tradition canonical usual worldwide'),
    (0.3, 'called used accepted'),
    (0.17, 'found'),
