    _, previous, earlier = carry if carry and carry[0] == doc else (doc, '', '')
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    modifier = earlier if previous == '-' else previous
    value = WORD_SCORES.get(word, 0.0)

    if word in {'known', '-known'}:
        value = KNOWN_MODIFIERS.get(modifier, 3.65)
        if modifier in {'is', 'was', 'are', 'were', 'been', 'also', 'now'}:
