    elif word == 'renowned' and modifier in {'world', 'internationally'}:
        value = 8.3 if modifier == 'world' else 6.0
    elif word == 'owned' and previous in {'ren', '-ren'}:
        value = 4.6 if previous == '-ren' else 3.0
    elif word == '-called':
        value = 1.65
    elif word == 'associated':
        value = 1.0
    elif word == 'example' and previous == 'for':
        value = 0.6
    elif word == 'name' and previous in {'given', 'common', 'household'}:
        value = 0.65 if previous == 'given' else 1.2

    if word in {'widely', 'commonly'}:
        value = 1.1
    if word in RECOGNITION_VERBS and modifier in FREQUENCY_WORDS:
        value += 3.2 if modifier == 'widely' else 1.35
    if word in {'called', 'referred'} and previous == 'also':
        value += 0.7
    if word == 'used' and previous in {'be', 'have', 'has', 'had'}:
        value = 0.1
    if word in {'established', '-established'} and modifier == 'well':
        value = 3.0 if word.startswith('-') else 2.0

    if previous in {'known', '-known'}:
        value += {'for': 6.8, 'as': 1.7, 'to': 1.55,
                  'by': 2.7, 'in': 1.5, 'that': 0.45}.get(word, 0.0)
