    if word == 'until':
        value = 0.52
    if word == 'respect':
        value = -0.3
    if word == 'to':
        if previous == 'respect':
            value = -1.1
        elif previous in {'get', 'learn', 'prefer'}:
            value = -0.85
        elif previous in {'important', 'expected', 'attention', 'regard',
                          'right', 'choose', 'tried', 'wanted', 'needed'}:
            value = -0.5

    # Familiarity stems, including inflections split across tokens.
    if word.startswith(('извест', 'bekannt', 'bekan')):
        value = 3.5
    if word.startswith(('conoc', 'conhec', 'популяр')):
        value = 2.2
    if word in {'ido', 'ida', 'idos', 'idas'}:
        if previous.startswith(('conoc', 'conhec')):
            value = 3.9
    if token.rstrip('的') in {'知名', '闻名', '聞名', '著名', '有名', '熟知'}:
        value = 4.0
    elif token in {'声誉', '聲譽'}:
        value = 2.0
    elif token in {'经典', '經典', '认可', '認可'}:
        value = 1.3
    elif token in {'大家', '为大家', '為大家'}:
        value = 1.0
    elif token in {'知', '知道', '名', '稱', '称', '認', '认', '叫'}:
        value = 0.65
    elif token == '的':
        value = 0.405
    elif '的' in token:
        value = 0.4 / len(token)
    elif token == 'の':
        value = 0.16

    return (doc, word, previous), float(value)

programs.haiku:
"""Fame and recognition, as word-level rules.

The component fires on words that say something is famous, renowned, well known,
recognised or widely used, and on "for" right after such a word ("known for",
"famous for"). Its strongest cases are "well known" (about 9), "known for" (about 6),
"famous" and "renowned" (about 5). Most other tokens are near zero.

Each rule is a list of words with the typical activation for that word, read from
the component's activations on training text. Context matters only in a few places:
"known" after "well" or "best", "for" after a fame word, "as"/"by" after "known",
and "used" after "widely" or "commonly". Everything else predicts 0.
"""

READS = ()

# Words saying something is famous or renowned.
FAMOUS = {
    "famous": 5.3, "renowned": 5.2, "notorious": 3.0, "infamous": 4.0, "fame": 2.4,
    "renown": 3.0, "celebrated": 1.0, "iconic": 2.9, "legendary": 1.7, "classic": 1.6,
    "知名": 4.2, "闻名": 4.2, "有名": 3.3, "著名": 3.3, "известн": 3.4, "bekannt": 3.4,
}
# Words saying something is recognised, noted, familiar or popular.
RECOGNISED = {
    "known": 4.0, "-known": 8.0, "popular": 1.9, "recognized": 2.0, "recognised": 1.4,
    "familiar": 1.0, "noted": 0.9, "remembered": 1.5, "respected": 1.0, "beloved": 1.4,
    "prominent": 0.9, "notable": 0.8, "reputation": 1.8, "associated": 1.0, "regarded": 1.3,
    "appreciated": 0.9, "популяр": 2.0, "声誉": 2.1, "公认": 2.7, "认可": 1.3, "conoc": 2.0,
}
# Weaker words for being used, shown, called or considered, plus the Chinese particle 的.
WEAK = {
    "的": 0.4, "used": 0.3, "shown": 0.6, "know": 0.7, "called": 0.3, "referred": 0.9,
    "considered": 0.4, "accepted": 0.6, "widespread": 1.0,
}
# Adverbs that intensify "known" and "used": "well known", "widely used".
INTENSIFIERS = {"well", "-well", "best", "widely", "commonly"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in FAMOUS:
        value = FAMOUS[word]
    elif word in RECOGNISED:
        value = RECOGNISED[word]
        if prev in INTENSIFIERS and word in ("known", "-known"):
            value = 9.0
    elif word in WEAK:
        value = WEAK[word]
        if prev in INTENSIFIERS and word == "used":
            value = 2.5
    elif prev in FAMOUS or prev in RECOGNISED:
        # The token right after a fame word: "for" in "known for", "as"/"by" after "known".
        if word == "for":
            value = 6.0
        elif word in ("as", "by", "to") and prev in ("known", "-known"):
            value = {"as": 1.6, "by": 2.8, "to": 1.6}[word]
        else:
            value = 0.0
    else:
        value = 0.0
    return carry, float(value)

