"""Use words that label a thing as familiar, notable, customary, or attributed.

The strongest cue is 'known' (also famous or renowned); smaller cues cover
popularity, customary frequency, and attribution/reporting words. The Chinese
modifier particle 的 gets a small prediction too. Other tokens are left quiet.
"""
READS = ()

FAMILIAR = {"known", "well-known", "famous", "renowned"}
REPUTATION = {"popular", "notable", "ubiquitous", "respected"}
COMMON = {
    "standard", "common", "typical", "typically", "usually", "generally",
    "often", "canonical", "usual",
}
ATTRIBUTION = {
    "noted", "associated", "referred", "called", "named", "considered",
    "regarded", "thought", "shown", "seen", "reported", "proven",
    "established", "recognized", "mentioned", "described", "used", "know",
}
CHINESE_MODIFIER_PARTICLE = {"的"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(
        " \t\r\n.,!?;:()[]{}\"'“”‘’—-"
    ).casefold()
    if word in CHINESE_MODIFIER_PARTICLE:
        value = 0.4
    elif word in FAMILIAR:
