            width = len(token)
            value = {1: -0.004, 3: -0.014, 4: 0.033,
                     5: 0.010}.get(width, 0.0)
        elif '\t' in token and '\n' not in token:
            value = 0.004
        else:
            value = 0.0
    elif stripped in SYMBOLS:
        value = SYMBOLS[stripped]
    elif len(stripped) == 1 and stripped in '0123456789':
        value = DIGITS[int(stripped)]
    else:
        word = stripped.lower()
        if word in WORD_RESPONSES:
            value = WORD_RESPONSES[word]
