"""Approximate an agency/public-action signal using words, not token IDs.

The principal cue is 'by': stronger after passive institutional actions,
weaker for arithmetic, formulas and credits. A small lexicon also recognizes
policy/action nouns (often stronger in the plural), implementing verbs, and
selected Chinese equivalents. Everything else predicts zero. This captures
a lexical pattern, not full grammatical understanding or every token effect.
"""
import re

READS = ()

# Singular stem -> typical strength, with a multiplier for plural forms.
NOUN_CLASSES = (
    (.60, 1.5, 'policy action intervention initiative decision'),
    (.20, 2.0, 'strategy tactic practice program programme'),
    (.30, 2.5, 'effort'),
    (.46, 2.7, 'measure countermeasure'),
    (.30, 2.0, 'regulation reform directive law'),
)
NOUNS = {w: (gain, plural) for gain, plural, words in NOUN_CLASSES
         for w in words.split()}
IMPLEMENTATION_WORDS = set(
    'implement implemented implementing implementation adopted adoption '
    'imposed enacted'.split()
)
STRONG_ACTIONS = set('adopted imposed enacted punished taken'.split())
AGENTS = set('approved proposed backed required used owned held supported '
             'followed directed controlled influenced inspired induced offered '
             'sponsored requested issued'.split())
ARITHMETIC = set('divide divided dividing divisible multiply multiplied '
                 'multiplying sides denominator times'.split())
FORMULAS = set('given obtained defined represented calculated characterized '
               'known computed denoted related separated connected'.split())
PUBLIC = set('government administrative political legal fiscal monetary economic '
             'austerity policy policies military urgent decisive stronger'.split())
PROTECTIVE = set('safety security defensive preventive precautionary protective '
                 'mitigation remedial health necessary appropriate'.split())
TAKING = set('take taking taken took adopt adopting adopted implement '
             'implementing enhance'.split())
CHINESE = {
    '行动': 1.2, '行動': 1.2, '采取': 1.5, '採取': 1.5, '出台': 1.5,
    '政策': .9, '决策': .9, '決策': .9, '制定': .9, '策略': .9, '手段': .9,
    '实施': .8, '實施': .8, '施': .8, '施行': .8, '策': .8, '措': .8,
}


def predict_token(token, trail, first):
    word = token.strip().lower()
    match = re.search(r'([A-Za-z]+)\s*$', trail)
    before = match[1].lower() if match else ''
    if word.lstrip('-/') == 'by':
        value = .92 if before.endswith(('ed', 'en')) else .64
        if before in STRONG_ACTIONS:
            value = 1.8
        elif before in AGENTS:
            value = 1.2
        elif before in ARITHMETIC:
            multiplying = before in {
                'multiply', 'multiplied', 'multiplying', 'times'}
            value = .44 if multiplying else .10
        elif before in FORMULAS:
            value = .44
        elif before in {'posted', 'start', 'begin', 'beginning'}:
            value = .28
        elif before in {'group', 'order', 'sort', 'sorted', 'grouped'}:
            value = .46
        if not match and not first:
            value -= .10
        if not token[:1].isspace():
            value -= .11
        if token.strip().isupper():
            value -= .16
        if re.search(r'\d\s*$', trail):
            value -= .08
        if match and match[1][:1].isupper() and match[1][1:].islower():
            value -= .08
        if first:
            value -= .16
        return value

    if word.endswith(('措施', '举措', '舉措')):
        return 2.36
    if word in CHINESE:
        return CHINESE[word]
    plural = word.endswith('s')
    if word.endswith('ies'):
        stem = word[:-3] + 'y'
    else:
        stem = word[:-1] if plural else word
    if stem in NOUNS:
        value, multiplier = NOUNS[stem]
        value *= multiplier if plural else 1.0
        if before in PUBLIC or before in TAKING:
            value += .9
        elif before in PROTECTIVE:
            value += .64
        elif before in {'privacy', 'cookie', 'insurance', 'medigap'}:
            value -= .44
    elif word == 'taken':
        value = .30
    elif word in IMPLEMENTATION_WORDS:
        value = .4
    elif word in {'legislation', 'enforcement', 'sanctions', 'lockdown'}:
        value = .76
    elif word in {'spending', 'expenditure', 'expenditures'}:
        value = .61
    else:
        return 0.0
    if not token[:1].isspace():
        if trail[-1:].isalpha():
            return 0.0
        value *= .5
    if token.strip()[:1].isupper():
        value *= .8
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        trail, first = '', True
    else:
        _, trail = carry
        first = False
    token = prefix.token_strings[-1]
    value = predict_token(token, trail, first)
    return (doc, (trail + token)[-128:]), float(value)

