programs.sol:
"""Sparse word-and-word-piece tuning in the first MLP.

The literal piece 'cho' fires negatively, as do echo and choice; completing
longer words usually weakens this response. Infection and presence words fire
positively. There are smaller positive responses to pregnancy and occurrence,
and to Java imports and Python exception handlers. A few immediate phrases
modify the response. These are lexical rules, not a general meaning detector.
"""

READS = ()


def lexical_response(raw, previous):
    spaced = raw.startswith((' ', '\t', '\n'))
    word = raw.strip().lstrip('._/#(\\')
    lower = word.lower()
    prev = previous.strip().lower()

    # The cho spelling: very strong as a bare piece, weaker in whole words.
    if lower == 'cho':
        return -4.0 if spaced else -4.5
    if lower == 'scho':
        return -2.5 if word[0].isupper() else -1.7
    if lower == 'chos':
        return -1.45
    if word == 'チョ':                 # Japanese spelling of "cho".
        return -2.45
    if lower == 'echo':
        if word[0].isupper():
            return -1.75
        return -2.7 if spaced else -3.1
    if lower in ('echoed', 'echoes', 'echoing'):
        return -1.4
    if lower in ('choice', 'choices'):
        value = -1.15 if lower.endswith('s') else -1.43
        if not spaced or word[0].isupper():
            value -= 0.3
        return value
    if lower in ('choose', 'chooses', 'chose', 'chosen', 'choosing'):
        return -0.2
    if lower == 'cholesterol' or word == '胆固醇':
        return -1.25
    if lower in ('chocolate', 'choir', 'psycho'):
        return -0.4

    # Infection vocabulary, including the Chinese/Japanese shared spelling.
    if lower == 'infection':
        return 2.35
    if lower == 'infections':
        return 1.9
    if lower == 'infected':
        return 1.4
    if lower in ('infect', 'infectious'):
        return 1.0
    if lower in ('fection', 'fections'):
        return 2.2 if previous.strip() == 'In' else 1.3
    if word == '感染':
        return 2.15
    if word == '感染者':
        return 1.3
    if word == '疫情':
        return 1.1
    if lower == 'pandemic':
        return 0.6

    # Presence/absence and event nouns; presence-of is particularly strong.
    if lower == 'presence':
        if not spaced:
            return 1.0
        return 1.6 if prev == 'the' else 1.35
    if lower == 'absence':
        return 0.4
    if lower in ('occurrence', 'occurrences'):
        return 0.55
    if lower in ('pregnancy', 'pregnancies'):
        return 0.9 if word[0].isupper() else 0.7
    if lower == 'pregnant':
        return 0.2
    if lower == 'of':
        if prev == 'presence':
            return 0.82
        if prev == 'absence':
            return 0.22
        if prev in ('choice', 'choices'):
            return -0.26
    if lower == 'for' and prev in ('choice', 'choices'):
        return -0.2

    # Programming syntax, not all uses of the programming-language name.
    if lower == 'java':
        if word != 'java':
            return 0.18
        return 1.05 if spaced and prev == 'import' else 0.45
