Each recognized delimiter gets a calibrated pulse that increases with document
prefix length. Message ends directly after tool-closing tags use weaker pulses.
Otherwise, recent Cyrillic text lowers delimiter pulses, CJK ideographs slightly
raise them, and a preceding tool exchange lowers them further. Role labels get
small pulses immediately after message starts.

Short Cyrillic fragments get a smaller response, strongest for capitals after
a non-letter. Leading spaces and fragment length adjust that response. Other
tokens predict zero. The document age and decaying script counts reset at each
new document. This omits individual words' idiosyncratic activation differences.
"""
import math

READS = ()

# (pulse with ample context, reduction for a very short document prefix)
BOUNDARIES = {
    '<|im_start|>': (4.07, 4.29),
    '<|im_end|>': (8.46, 7.72),
    '<tool_call>': (6.15, 5.13),
    '</tool_call>': (6.07, 4.69),
    '<tool_response>': (5.38, 4.81),
    '</tool_response>': (4.42, 4.44),
    '<think>': (4.47, 4.41),
    '</think>': (6.26, 5.74),
}
TOOL_ENDS = {'</tool_call>', '</tool_response>'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, last_tool_end = 0, '', ''
        cyrillic, ideographs, latin = 0.0, 0.0, 0.0
    else:
        _, age, previous, last_tool_end, cyrillic, ideographs, latin = carry

    short_context = 1.0 / math.sqrt(age + 1)
    mostly_cyrillic = cyrillic > 5 and cyrillic > latin / 3
    mostly_ideographic = ideographs > 5 and ideographs > latin / 3
    value = 0.0
    if s in BOUNDARIES:
        pulse, reduction = BOUNDARIES[s]
        value = pulse - reduction * short_context
        if s == '<|im_end|>' and previous in TOOL_ENDS:
            pulse = 4.66 if previous == '</tool_call>' else 5.04
            value = pulse - 6.0 * short_context
        else:
            if mostly_cyrillic:
                value -= 1.85 if s == '<|im_end|>' else 1.0
            elif mostly_ideographic:
                value += 0.15
            if last_tool_end:
                value -= 0.15 if s.startswith('</') else 0.45
    elif previous == '<|im_start|>':
        if s == 'assistant':
            value = 0.9 - 0.85 * short_context
        elif s == 'user':
            value = 0.76 - 1.1 * short_context
    else:
        letters = [ch for ch in s if '\u0400' <= ch <= '\u052f']
        if letters:
            n = len(letters)
            spaced = s.startswith(' ')
            capital = letters[0].isupper()
            boundary = not previous or not previous[-1].isalpha()
            if boundary:
                if capital:
                    value = max(0.2, 1.6 - 0.25 * (n - 1) - 0.4 * spaced)
                else:
                    value = 0.85 / math.sqrt(n) - 0.1 * spaced
            elif spaced:
                if capital:
                    value = max(0.0, 0.4 - 0.2 * (n - 1))
                else:
                    value = 0.17 if n == 1 else (0.05 if n == 2 else -0.03)

    if s in TOOL_ENDS:
        last_tool_end = s
    elif s == '<|im_end|>' and previous not in TOOL_ENDS:
        last_tool_end = ''
    # A decaying tally describes the script of recent text, not model attention.
    cyrillic = 0.98 * cyrillic + sum('\u0400' <= ch <= '\u052f' for ch in s)
    ideographs = 0.98 * ideographs + sum('\u4e00' <= ch <= '\u9fff' for ch in s)
    latin = 0.98 * latin + sum('a' <= ch.lower() <= 'z' for ch in s)
    carry = (doc, age + 1, s, last_tool_end, cyrillic, ideographs, latin)
    return carry, float(value)

