PUNCT_END = set(".?!。？！)”»")
CLOSE_TOOL = {"</tool_call>", "</tool_response>"}
MARKERS = {
    "</think>": 5.5,
    "<tool_call>": 5.3,
    "</tool_call>": 5.5,
    "<tool_response>": 4.5,
    "</tool_response>": 4.0,
    "<think>": 3.8,
