            value = 8.0
        elif prev in CLOSE_TOOL:
            value = 4.3
        else:
            value = 6.0
    elif cur == "<|im_start|>":
        value = 0.0 if prev == "<|endoftext|>" else 3.3
    elif cur in MARKERS:
        value = MARKERS[cur]
    elif cur.strip() == "assistant":
        value = 0.8
    elif is_cyrillic_capital(cur):
        value = 1.3
    else:
        value = 0.0
    return None, float(value)

