        if 0 < position < 32:
            value += 0.35 if upper else 0.10
        elif 32 <= position < 128:
            value += 0.10 if upper else 0.03
        return carry, float(value)

    letters = token.lstrip('_./-(')
    value = 0.0
    if len(letters) == 2 and letters.isascii() and letters.isalpha():
        if letters in ('PP', 'pp'):
            value = 1.25 if letters.isupper() else 0.76
        elif letters in ('Ps', 'ps'):
