    return len(text) == 1 and text in DIGITS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if token == '<|im_start|>':
        value = 1.14 if previous else 0.22
    elif token == '</think>':
        value = 1.33
    elif token == '<think>':
        value = 0.38
    elif token == '<|im_end|>':
        value = -0.116
    elif token in ('</tool_call>', '</tool_response>'):
        value = -0.13
    elif is_digit(token):
        if previous == '.':
            if not before_previous:
                value = 1.0
            elif before_previous.lstrip('.') in ('sub', 'sup'):
                value = 0.05
            elif is_digit(before_previous):
                value = 0.64
            else:
                value = 0.42
            if token == '0':
                value += 0.15
        elif previous.endswith('.') and previous.count('.') == 1:
            value = 0.57 if token == '0' else 0.42
    elif token == 'n' and previous[-1:].lower() == 'w':
        value = 0.55
    elif (previous[-1:].isalpha() and token.islower()
          and len(token) in (2, 3) and token.endswith('n')
          and token[0] in 'aeiou'
          and (len(token) == 2 or token[1] in 'rw')):
        value = 0.07
    elif token == ' .':
        if previous == ' .' or not previous:
            value = 0.46
        elif previous.endswith('.'):
            value = 0.33

    return (doc, token, previous), float(value)

