    if not tail:
        if code_like:
            return -0.05 if math_like else 0.11
        return 0.20 if math_like else 0.46
    if code_like:
        return 0.02 if math_like else 0.05
    return 0.11 if math_like else 0.08


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        recent = ""
    else:
        recent = carry[1]

    context = (recent + token)[-30:]
    code_like = any(mark in context for mark in _CODE_MARKS)
    math_like = any(mark in context for mark in _MATH_MARKS)

    if "）" in token:
        value = 0.0 if code_like else 1.4
    elif ")" in token:
        after = token.rsplit(")", 1)[-1]
        value = _closing_response(after, code_like, math_like)
    elif "]" in token:
        value = 0.04
    else:
        value = 0.0

    return (document, context), value

programs.sol:
"""Recognize Boolean types and words for truth tests and binary choices.

The largest negative output is for bool/boolean. Smaller negative outputs
mark truth values, flags, toggles, yes/no questions and related logic words.
Case and attached punctuation distinguish common code spellings. A preceding
return arrow weakens a type response; copulas/articles weaken true/false,
while return/returns strengthens them. Document boundaries are respected.
Boolean-name fragments are included. Other tokens receive zero.
This is lexical recognition, not truth reasoning.
"""
import re

READS = ()

TYPES = {
    'bool': -8.3, 'Bool': -6.7, 'BOOL': -7.0,
    'boolean': -8.0, 'Boolean': -7.2, 'BOOLEAN': -8.0,
    'booleans': -6.2, 'oleans': -6.2, 'stdbool': -9.2,
    'getBoolean': -5.2,
}
LITERALS = {
    'true': -1.8, 'True': -2.2, 'TRUE': -3.0,
    'false': -2.3, 'False': -2.45, 'FALSE': -3.2,
}
CHOICES = {
    'flag': -3.05, 'flags': -2.1, 'flagged': -1.35,
    'status': -1.3, 'toggle': -2.35, 'checkbox': -3.7,
    'radiobutton': -2.0, 'whether': -1.5, 'yes': -1.05,
    'truth': -1.0, 'logic': -0.4, 'logical': -1.25,
    'conditional': -0.8, 'optional': -1.6, 'nullable': -1.1,
    'asserttrue': -1.5, 'assertfalse': -2.9,
    'tobetruthy': -2.55, 'tobefalsy': -2.2,
    'binary': -0.3, 'bit': -0.3, 'percentage': -0.8,
    'enabled': -0.5, 'disabled': -0.5,
    '是否': -2.8, '否': -3.6, '与否': -3.4, '布尔': -5.7,
    '有没有': -1.3, '能否': -1.4, '吗': -0.7, '嗎': -0.65,
}
CAPITALIZED = {
    'Flag': -3.3, 'Flags': -2.3, 'Status': -1.65,
    'Toggle': -3.25, 'Whether': -1.8, 'Optional': -1.05,
}
SYMBOLS = {'✓': -1.0, '✔': -0.9, '✅': -0.8,
           '✗': -0.6, '❌': -0.7, '¬': -2.8}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    match = re.fullmatch(r'([^\w]*_*)(\w+)([^\w]*)', token)
    lead, word = (match[1], match[2]) if match else ('', token.strip())
    low = word.lower()
    previous = ''
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()
    value = CAPITALIZED.get(word, CHOICES.get(low, 0.0))
    if word in TYPES:
        value = TYPES[word]
        if not lead or lead == '.':
            value = {'bool': -9.8, 'Bool': -8.0, 'Boolean': -7.9}.get(word, value)
        elif not lead.isspace():
            value *= 0.8 if '<' in lead or ']' in lead else 0.94
        if lead.isspace():
            if previous.endswith(('->', '=>')):
                value += 1.15
            elif previous.endswith(':'):
                value += 0.5
            elif previous in {'private', 'static', 'const', 'inline', 'return'}:
                value -= 0.8
    elif word in LITERALS:
        value = LITERALS[word]
        if not lead.isspace() and word.islower() and lead != ':':
            value -= 0.35
        if previous in {'return', 'returns'}:
            value -= 0.35
        elif previous in {'is', 'are', 'was', 'be', 'the', 'a', 'not'}:
            value += 0.35
    elif low == 'void':
        value = -1.95 if lead.isspace() else -2.2
        if lead == '(':
            value = -1.4
    elif low == 'null':
        value = -0.55 if token == ' NULL' else -0.2
    elif word == 'string':
        value = -0.6 if lead in {'', '.'} else -0.15 if lead.isspace() else 0.0
    elif low == 'bo':
        value = -0.95 if lead.isspace() else -0.75 if word == 'Bo' else -0.25
    if token.strip() in SYMBOLS:
        value = SYMBOLS[token.strip()]
    return None, float(value)

