programs.sol:
"""English auxiliary and infinitive constructions, approximated from two tokens.

Contracted auxiliaries (it's, we're, I'll) have the strongest response; ordinary
possessive 's is quiet. Modals respond strongly after personal pronouns, and
infinitival 'to' after words of intention, effort, ability, or prospect.
Smaller responses cover inverted questions and related verbs/adverbs.
Numbers are approximate activation strengths, not grammatical probabilities.
"""
import re

READS = ()
PERSONAL = {'i', 'you', 'we', 'he', 'she', 'they', 'it'}
MODAL_SCALE = {
    'can': 1.08, 'could': .85, 'will': .93, 'would': .91,
    'should': 1.12, 'may': .98, 'might': 1.10, 'must': .88,
    'shall': .75, 'cannot': .65,
}
MODALS = set(MODAL_SCALE)
SUBJECT = {
    'i': 1.2, 'you': 1.65, 'we': 1.7, 'he': 1., 'she': 1.,
    'they': .95, 'it': .7, 'there': .7, 'one': .8,
    'this': .35, 'who': .4, 'which': .2,
}
BE = {'is', 'are', 'am', 'was', 'were'}
HAVE_DO = {'have', 'has', 'had', 'do', 'does', 'did'}
CONTRACTIONS = {"'re": 2.25, "'m": 1.95, "'ll": 2.45,
                "'ve": 1.95, "'d": 2.5}
S_CONTRACTIONS = {
    'it': 2.65, 'he': 2.9, 'she': 2.9, 'there': 2.9,
    'that': 2.1, 'what': 2.1, 'who': 2.3, 'here': 1.2,
    'where': 1.2, 'how': 1.2, 'one': .6,
}


def forms(roots):
    """A few ordinary English inflections, to avoid enumerating each form."""
    result = set(roots)
    for w in roots:
        result.add(w + 's')
        if w.endswith('e'):
            result.update((w + 'd', w[:-1] + 'ing'))
        elif w.endswith('y'):
            result.update((w[:-1] + 'ies', w[:-1] + 'ied', w + 'ing'))
        else:
            result.update((w + 'ed', w + 'ing'))
    return result


INTENTION = forms({'want', 'wish', 'try', 'prefer'}) | {
    'needs', 'ought', 'willing', 'preferred', 'preferring'}
EFFORT_ABILITY = forms({'attempt', 'aim', 'help', 'expect', 'learn',
                        'refuse'}) | {
    'able', 'unable', 'ability', 'have', 'has', 'had', 'how', 'like',
    'easy', 'easier', 'difficult', 'hard', 'important', 'impossible',
    'better', 'best', 'helpful'}
PROSPECT = forms({'seem', 'decide', 'fail', 'tend', 'start', 'continue',
                  'choose', 'ask'}) | {
    'likely', 'possible', 'necessary', 'ready', 'expected', 'supposed',
    'needed', 'begin', 'began', 'beginning', 'opportunity', 'desire', 'forced'}
PURPOSE = {'going', 'required', 'designed', 'intended', 'enough', 'chance',
           'time', 'order', 'plan', 'plans', 'meant', 'happy', 'free', 'similar'}
TO_MODERATE = {'is', 'be', 'was', 'are', 'what', 'not', 'way', 'ways',
               'equal', 'lead', 'leads', 'leading', 'led', 'sure'}


def response(raw, previous):
    word = raw.strip().replace('’', "'").lower()
    if word == "'s":
        value = S_CONTRACTIONS.get(previous, 0.)
        return value + (0.1 if value and '’' in raw else 0.)
    if word in CONTRACTIONS:
        return (CONTRACTIONS[word] if previous in
                PERSONAL | {'there', 'who', 'what', 'that'} else 0.)
    if not raw.startswith(' '):
        return 0.
    if word == 'to':
        if previous in {'want', 'need', 'wish'}:
            return 1.68
        for words, strength in ((INTENTION, 1.4), (EFFORT_ABILITY, 1.1),
                                (PROSPECT, .82), (PURPOSE, .4),
                                (TO_MODERATE, .65)):
            if previous in words:
                return strength
        if previous in {'you', 'us', 'me', 'him', 'her', 'them'}:
            return .5
        return 0.
    if word in PERSONAL and previous in MODALS:
        return .8 if previous in {'can', 'could'} else .5
    if word in MODALS:
        if previous == 'that':
            return 0.
        return MODAL_SCALE[word] * SUBJECT.get(previous, -.05)
    if word in BE | HAVE_DO:
        if previous in PERSONAL:
            if previous == 'they':
                return .53
            if previous == 'we':
                return .74
            if previous == 'it' and word in HAVE_DO:
                return .42
            return .65
        if previous == 'there':
            return .85 if word in BE else .5
        return {'who': .28, 'which': .08 if word in BE else 0.,
                'that': -.10}.get(previous, 0.)
    if word == 'need':
        if previous in PERSONAL | MODALS | {'also'}:
            return 1.32 if previous == 'we' else 1.08
        if previous in {'not', "'t"}:
            return .4
        return 0. if previous in {'the', 'a', 'no'} else .45
    if word in {'want', 'wants', 'wanted'}:
        return .45 if previous in PERSONAL | MODALS else 0.
    if word in {'mean', 'means', 'require', 'requires', 'implies'}:
        if previous in PERSONAL | MODALS | {'this', 'that', 'which'}:
            return .75
        return 0. if previous in {'the', 'a', 'of', 'by'} else .35
    if word in {'help', 'like'}:
        return .65 if previous in PERSONAL | MODALS | {
            "'d", "'ll", "'t", 'also'} else 0.
    if word in {'also', 'often', 'usually', 'typically', 'probably'}:
        if previous in PERSONAL | MODALS:
            return .5
        return 0. if previous in {',', 'and', 'see'} else .3
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    value = response(raw, previous)
    # Recognize a word even when its opening quotation mark shares the token.
    match = re.fullmatch(r'[\s\W]*([A-Za-z]+)', raw)
    word = match.group(1).lower() if match else raw.strip().lower()
    return (doc, word.replace('’', "'")), float(value)

programs.haiku:
"""Layer-0 MLP feature for the verb-like word that a subject pronoun hands to its
predicate. It fires on
  - contraction clitics after a pronoun: it'S, that'S, there'S, you'RE, I'M, you'LL,
    we'VE, I'D (about 2 to 2.7);
  - modal verbs after a subject pronoun: you CAN, we WILL, I SHOULD (about 1 to 1.7;
    lower after it/he/she/there);
  - be/have auxiliaries after a subject: it IS, there WAS, we ARE, he HAS (about 0.6-0.7);
  - 'need' after a subject, and the infinitive 'to' after words that take one
    (want TO, need TO, able TO, how TO) (about 1.3).
Everything else, including the prepositional 'to' (according to, due to), is about zero.
"""

READS = ()

PERSONAL = {"you", "we", "i", "they"}
SUBJECTS = PERSONAL | {"it", "he", "she", "there", "that", "what", "here", "who"}
CLITICS = {"m": 2.1, "re": 2.2, "ll": 2.5, "ve": 2.1, "d": 2.5, "s": 2.7}
MODALS = {"can": 1.7, "will": 1.5, "would": 1.0, "should": 1.0, "may": 1.0,
          "might": 1.0, "must": 1.0, "could": 1.0, "shall": 1.0}
BE_HAVE = {"is": 0.7, "are": 0.7, "was": 0.6, "were": 0.5, "am": 0.7,
           "has": 0.7, "have": 0.6, "had": 0.6}
TO_AFTER = {
    "want", "wants", "wanted", "need", "needs", "needed", "try", "tries", "trying", "tried",
    "have", "has", "had", "able", "unable", "how", "like", "began", "begins", "start",
    "started", "decided", "decides", "learn", "failed", "difficult", "easy", "hard",
    "impossible", "important", "possible", "ready", "likely", "necessary", "expected",
    "supposed", "ability", "opportunity", "way", "ways", "seem", "seems", "continue",
    "continued", "lead", "leads", "led", "aim", "aims", "attempt", "helps", "better",
    "wish", "sure", "is", "equal", "equivalent", "leading", "asked", "designed",
}


def _word(s):
    return s.strip().replace("’", "'").lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = _word(toks[-1])
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    prev = "" if new_doc else _word(toks[-2])
    subject = prev in SUBJECTS
    value = 0.0
    if cur.startswith("'") and cur[1:] in CLITICS:
        value = CLITICS[cur[1:]] if (cur != "'s" or prev in SUBJECTS) else 0.0
    elif cur in MODALS and subject:
        value = MODALS[cur] * (1.0 if prev in PERSONAL else 0.5)
    elif cur in BE_HAVE and subject:
        value = BE_HAVE[cur]
    elif cur == "need" and subject:
        value = 1.0
    elif cur == "to" and prev in TO_AFTER:
        value = 1.3
    return carry, float(value)

programs.luna:
"""A lexical sketch: boost selected English grammar words and clitics.
For the token ``to``, a short list of preceding cues gets a larger bump;
all other tokens get zero.
"""
READS = ()

MODALS = {"can", "could", "may", "might", "must", "shall", "should", "will", "would"}
TO_CONTEXT = {"can", "could", "may", "might", "must", "shall", "should", "will", "would",
              "need", "needs", "needed", "want", "wants", "wanted",
              "have", "has", "had", "able", "going", "ought", "how", "is", "equal"}
