AUXILIARIES = {"am", "is", "are", "was", "were", "have", "has", "had", "do", "does", "did"}
NEED_OR_WANT = {"need", "needs", "needed", "want", "wants", "wanted", "require", "requires", "required"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
