programs.haiku:
"""Words of strength. The component answers to words meaning strength: strong, strength
and their relatives (strongest, strengthen), and the Chinese 强/強 and Korean 강 in
compounds such as 加强, 增强, 强化, 强调; more weakly to words of weakness (weak, 弱);
and only faintly to milder words of force, power and intensity (powerful, force, hard,
tough, intense, stress, 力). Every other token gets 0."""

READS = ()

MILD = {"powerful", "power", "enhance", "enhanced", "enhancing", "enhances", "enhancement",
        "force", "forte", "tough", "stiff", "hard", "harsh", "intense", "intensity", "severe",
        "severity", "stress", "potent", "mighty", "vigor", "vigorous", "heavily", "highly",
        "difficult", "fort", "bright", "reinforcement", "reinforce", "improve",
        "猛", "烈", "雄", "刚", "硬"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
