STRONG_WORDS = {"strong", "strength"}
MID_STRENGTH_WORDS = {"weak", "strengthened"}

DEGREE_AND_QUALITY_WORDS = {
    "power", "powerful", "hard", "tough", "reinforce", "enforce",
    "vigorous", "vigorously", "superior", "bright", "brightness",
    "dark", "poor", "difficult", "difficulty", "improve", "improved",
    "contrast", "thin", "potężny", "mejorar", "kräftig", "stark",
    "schwach", "かなり",
}

CHINESE_STRONG_MARKS = ("强", "強")
CHINESE_QUALITY_MARKS = ("坚", "堅", "硬", "力", "薄")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
