programs.sol:
"""Lexical approximation: positive age/newness phrases, negative thinking words.

It pulses on the word after new/old/current/present/etc., most strongly for
versions, inventions, research and periods of time. Hyphenated old-style
phrases are stronger still. 思 ('think') and troubleshooting are negative.
It misses most small background responses and fine contextual differences.
"""
READS = ()
AGE = set('''new newer newest old older oldest present current latest recent
previous modern ancient early late future past former original initial
revised updated contemporary improved modified'''.split())
ARTIFACTS = set('invention version versions edition editions implementation'.split())
RESEARCH = set('study studies research work understanding'.split())
PERIODS = set('day days year years time times era period season seasons week'.split())
OLD_STYLE = set('school style fashion fashioned world testament'.split())
OTHER_PHRASES = set('''life design technology model detection generation
generations friends enough'''.split())
# Chinese/Japanese words for newness, age and the present.
HAN_AGE = set('新 老 旧 古 今 最新 最近 古代 原 的新 新的 全新 现代 現'.split())
THOUGHT = {'思': -1.53, '思考': -1.10, '思索': -1.10, '反思': -0.90,
           'troubleshooting': -0.90, 'leshoot': -0.90, 'brainstorm': -0.65}


def activation(token, previous):
    text = token.strip()
    word, before = (t.strip().lstrip('._-(').lower() for t in (token, previous))
    if word in THOUGHT:
        return THOUGHT[word]
    if word in {'think', 'analysis', 'reasoning', 'debug',
                'write', 'writing', 'note', 'noted'}:
        return -0.16
    if word in {'thinking', 'thinker', 'thinkers', 'debugging'}:
        return -0.26
    if word in {'ing', 'ging'} and before in {'reason', 'debug', 'brainstorm'}:
        return -0.70
    if token.startswith('.') and word == 'error':
        return -0.65 if before == 'console' else -0.35
    value = 0.0
    if word == 'invention':
        value = 0.34
    elif word in ARTIFACTS and text == word:
        value = 0.13
    if before in AGE and any(c.isalpha() for c in token):
        value = 0.08
        if word in ARTIFACTS:
            value = 1.00
            if before in {'old', 'older'} and word.startswith('version'):
                value = 1.75
        elif word in RESEARCH:
            value = 0.35 if word in {'studies', 'work'} else 0.65
        elif word in PERIODS:
            value = 0.32 if word == 'years' else 0.55
            if (before in {'old', 'modern', 'present', 'previous'}
                    and word in {'day', 'days', 'time', 'times'}):
                value = 1.20
        elif word in OLD_STYLE:
            value = 1.20 if before in {'old', 'older'} else 0.55
        elif word in OTHER_PHRASES:
            value = 0.55
        elif word == 'working':
            value = 0.30
        if token.startswith('-') and word in OLD_STYLE | {'day'}:
            value = 1.80
        if previous.strip() in {'Old', 'New'} and token[:1].isalpha():
            value = 0.90 if before == 'old' else 0.40
        if before == 'new' and word == 'york':
            value = 0.13
    if previous.strip() in HAN_AGE:
        value += 0.70 if previous.strip() == '旧' else 0.32
        if text in {'版', '版本', '式', '規', '朽'}:
            value += 0.85
    elif text in {'版', '版本'}:
        value += 0.16
    return value


def step(carry, prefix, upstream):
    document, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    value = activation(token, previous)
    if (carry and carry[0] == document and '\ufffd' in token
            and prefix.text_prefixes[-1].endswith('思')):
        value = -1.53
    return (document, token), float(value)

programs.luna:
"""Use phrase cues for research and versions, plus small word-form biases.

The strongest repeated cues are “present invention/study” and “current/latest
version”. In ordinary text, version/study words and -tion nouns lean positive,
while think words lean negative; otherwise this predicts zero.
"""

READS = ()

def step(carry, prefix, upstream):
    end = len(prefix.token_ids)
    start = end - 1
    document = prefix.document_ids[-1]
    while (start > 0 and end - start < 4
           and prefix.document_ids[start - 1] == document):
        start -= 1
    recent = prefix.token_strings[start:end]
    words = "".join(recent).lower().split()
    if not words:
        return None, 0.0
    clean = lambda word: word.strip(".,:;!?()[]{}\"'`")
    head = clean(words[-1])
    modifier = clean(words[-2]) if len(words) > 1 else ""

    if modifier == "present" and head == "invention":
        return None, 0.90
    if modifier == "present" and head in {"study", "day"}:
        return None, 0.80
    if head == "version" and modifier in {"latest", "current", "original"}:
        return None, 0.95
    if modifier in {"new", "past", "current"} and head == "year":
        return None, 0.52
    if modifier in {"new", "recent"} and head in {"research", "release"}:
        return None, 0.55
    if modifier == "new" and head in {"generation", "generations"}:
        return None, 0.62
    if modifier == "revised" and head == "edition":
        return None, 0.55

