"""Local lexical detector for attributes, membership, and attraction.

Attribute names and their `attr` abbreviation give the largest negative
pulse. The response is weaker for plurals, compound names, and derivatives.
Some translations of attribute/belonging and related vocabulary also give
negative pulses. This is a spelling-based approximation, not a parser.
"""

READS = ()
EDGE_PUNCTUATION = '._()[]{}<>\'"@'
ATTRIBUTE_NAMES = {'attr', 'attrs', 'attribute', 'attributes'}
ATTRIBUTE_BUILTINS = {'getattr', 'setattr', 'delattr', 'hasattr'}
AFFILIATION = {'所属', '归属', '直属', '所屬', '歸屬', '直屬'}
BELONGING = {'属于', '归属于', '隶属于', '不属于', '屬於', '歸屬於'}


def lexical_score(text):
    raw = text.strip()
    stem = raw.strip(EDGE_PUNCTUATION)
    word = stem.lower()
    if word in ATTRIBUTE_NAMES:
        if stem.isupper():
            return -4.4
        value = -5.2 if word.endswith('s') else -6.0
        if word == 'attr' and text in {'attr', '.attr'}:
            value = -6.8
        elif raw.startswith(('(', '[', '.')) or (
                raw.startswith('_') and word != 'attr'):
            value *= 0.83
        if (text[:1].isspace() and stem[:1].isupper()
                and not word.endswith('s')):
            value *= 0.85
        return value
    if word in ATTRIBUTE_BUILTINS:
        return -5.9 if word == 'hasattr' else -4.5
    if word in {'getattribute', 'setattribute'}:
        return -6.8
    if word in {'addattribute', 'removeattribute'}:
        return -4.2
    if word in {'attributed', 'attributing', 'atributo', 'atributos'}:
        return -2.3
    if word.startswith('attribute'):
        return -3.3
    if 'attribute' in word or word.endswith('attr'):
        return -2.0
    if word in {'attrib', 'atrib'}:
        return -2.5
    if word.startswith(('attrib', 'atrib')):
        return -1.2
    if word in {'属', '屬'}:
        return -4.8
    if word in {'属性', '屬性'}:
        return -3.6
    if word in AFFILIATION:
        return -2.6
    if word in BELONGING:
        return -1.7
    if word in {'속', '속성', 'thuộc'}:
        return -2.1
    if word == 'props':
        return -1.6 if stem.startswith('P') else -0.95
    if word.startswith('belong'):
        return -1.05
    if word.startswith('attract'):
        return -0.9 if word in {'attract', 'attracting'} else -1.35
    if word in {'吸引', '魅力', '吸引力'}:
        return -1.2
    if word in {'trait', 'traits', 'feature', 'features'}:
        return -0.35
    if word.startswith(('possess', 'assign')):
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = lexical_score(text)
    # A byte-split Chinese character may only become readable on this token.
    if '\ufffd' in text:
        suffix = prefix.text_prefixes[-1][-2:]
        if suffix in {'属性', '屬性'}:
            value = -4.4
        elif suffix[-1:] in {'属', '屬'}:
            value = -4.8
    return None, value

