"""Approximate the dominant response to typographic list markers, especially •.
Ordinary token-specific fluctuations are left unmodeled.
The strongest response is at a document's start; it gradually weakens later,
with further reductions for blank lines, leading spaces, and indentation.
It also recognizes split UTF-8 encodings of private-use PDF list markers.
Check/cross marks are weakly negative.  A few English phrase endings have
separate responses: 'used to', 'role of', and 'method of'.
"""
import math

READS = ()

# Related list-marker glyphs, with their different typical strengths.
LIST_MARKERS = {
    '●': 0.75,
    '■': 0.50,
    '▪': 0.36,
    '◦': 0.31,
    '►': 0.17,
    '◆': 0.23,
    '♦': 0.25,
    '‧': 0.26,
    '∙': 0.18,
    '・': 0.12,
    '·': 0.04,
    '□': 0.11,
}
CHECK_OR_CROSS = frozenset('✓✔✅✗✘❌')
PRIVATE_USE_LIST_MARKERS = frozenset(('\uf097', '\uf0a7', '\uf0b7'))
# Qwen tokens for UTF-8 EF 82 (optionally preceded by a space):
# the unfinished prefix of private-use characters U+F080..U+F0BF.
PRIVATE_USE_PREFIX = frozenset((76986, 68298))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, previous, pending = 0, '', False
    else:
        pos, previous, pending = carry[1] + 1, carry[2], carry[3]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = -0.0015
    starts_private = prefix.token_ids[-1] in PRIVATE_USE_PREFIX
    if starts_private:
        value = 0.45 if token.startswith(' ') else 0.55
    elif pending:
        # Decode only when the second token completes a private-use symbol.
        character = prefix.text_prefixes[-1][-1]
        if character in PRIVATE_USE_LIST_MARKERS:
            value = 0.66
        elif '\uf080' <= character <= '\uf0bf':
            value = 0.14
    elif token in ('•', ' •'):
        value = 2.33 if pos == 0 else 1.73 - 0.088 * math.log1p(pos)
        if token.startswith(' '):
            value -= 0.055
        if '\n\n' in previous:
            value -= 0.095
        elif previous and not previous.strip(' \t'):
            value -= 0.36
    elif word == '•':  # Bullet and line breaks within one token.
        value = 0.55
    elif word in LIST_MARKERS:
        value = LIST_MARKERS[word]
        if token.startswith(' '):
            if word == '●':
                value = 0.57
            elif word == '►':
                value = 0.30
    elif word in CHECK_OR_CROSS:
        value = -0.10
    elif token == ' to':
        before = previous.strip().lower()
        if before == 'used':
            value = 0.386
        elif before in ('use', 'utilized'):
            value = 0.30
    elif token == ' of':
        before = previous.strip().lower()
        if before == 'role':
            value = -0.39
        elif before == 'method':
            value = 0.31
    elif word == 'bullet' and previous.endswith('\\'):
        value = 0.39  # TeX \bullet.
    return (doc, pos, token, starts_private), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:5684 -- the word "to".

What it does: this direction of the layer-0 MLP output is switched on by the
word "to" (as "to" + verb, or as a preposition). It is near zero on almost every
other token. How strongly it fires on "to" depends on the word just before:

* after a noun or verb of access, means, direction or result ("way to",
  "access to", "solution to", "how to", "time to", "lead(s) to", "approach to",
  "welcome to", "here to") it is strongest;
* after motion or "go"-type words ("go to", "is up to", "back to", "going to")
  it is fairly strong;
* after punctuation or a joining word (", to", "and to", "as to", "not to") it
  is fairly strong;
* after a pronoun, a number or a closing bracket it is moderate, and after other
  ordinary words it is moderate-to-strong;
* after verbs and adjectives such as "order to", "respect to", "designed to",
  "important to", "refer to" it is near zero;
* after a verb that takes a "to" complement of wanting, needing, trying or
  using ("want to", "need to", "try to", "used to", "failed to") it is weak, and
  after relational words ("due to", "related to", "equal to", "proportional to")
  it is weak or slightly negative.

Capitalised "To" at the start of a sentence is strong. "to" without a space and
"TO", "toward(s)" are moderate.

Predictions are in the component's own activation units (mean on " to" ~0.66).
This is a word-class rule, not a lookup of token ids: it reads only the current
token and the one before it, within the same document.
"""

READS = ()

# Verbs and adjectives that take a "to" complement of wanting, needing, trying,
# using or permission: "want to", "need to", "tried to", "allowed to", ...
CONTROL = set(
    "want wants wanted wanting need needs needed try tries tried trying failed "
    "fails fail used use had have has required expected supposed allowed seem "
    "seems seemed happy refused wish desire able unable willing".split()
)

# Words that tie a "to" to a quantity or comparison: "due to", "related to", ...
RELATIONAL = set(
    "due owing related relating relates relative equal proportional similar "
    "comparable according compared prior".split()
)

# Nouns and verbs of access, means, direction, result: "way to", "access to", ...
GOAL = set(
    "way ways access solution solutions answer approach distance how time chance "
    "opportunity means exposure dedication commitment response responses method "
    "welcome lead leads leading led here forward closer".split()
)

# Motion and "go"-type words: "go to", "back to", "is up to", ...
MOTION = set(
    "go went goes going come came get got move moving moved switch return "
    "returned respond back out up down over is".split()
)

PRONOUNS = set("me you them him her us it".split())

# Punctuation and joining words before "to": ", to", "and to", "as to", "not to".
JOINERS = set(", . and or but as on that what not ` \" ' : ; ( :".split())

# Verbs and adjectives whose "to" is weak: "order to", "respect to", "designed to".
WEAK = set(
    "order addition ability attempt decided decide continue refer refers referred "
    "referring apply applied applies choose tends designed important necessary "
    "enough like respect corresponding".split()
)


def _previous_word(prefix):
    """The word before the current token, lowercased, or '' at a document start."""
    if len(prefix.token_strings) < 2:
        return ""
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-2].strip().lower()


def _to_value(prev):
    """Activation on " to", by the word before it."""
    if prev in RELATIONAL:
        return -0.1
    if prev in CONTROL:
        return -0.2
    if prev in GOAL:
        return 2.0
    if prev in MOTION:
        return 1.3
    if prev in PRONOUNS:
        return 0.8
    if prev in WEAK:
        return 0.0
    if prev in JOINERS or prev in (")", "]", '"', "'") or prev.isdigit():
        return 1.0
    return 0.7


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " to":
        value = _to_value(_previous_word(prefix))
    elif token in ("To", " To"):
        value = 1.6
    elif token in ("to", " TO", "-to", "_to", " toward", " towards"):
        value = 1.0
    else:
        value = 0.0
    return carry, float(value)

