import re

READS = ()


def _meaning(word):
    """A rough response scale for familiar words in the around/round family."""
    if word == "around":
        return 2.6
    if word == "about":
        return 0.8
    if word.endswith("circumference"):
        return 3.3
    if word.endswith("circles"):
        return 3.0
    if word.endswith("circle"):
        return 4.5
    if word in {"sphere", "spheres"}:
        return 2.4
    if word in {"orbit", "orbits"}:
        return 1.0
    if word in {"loop", "loops"}:
        return 1.2
    if word in {"round", "rounds", "yearround"} or word.endswith("-round"):
        return 1.2
    if word.endswith("rounding"):
        return 0.85
    if word in {"ring"} or word.endswith("-ring"):
        return 1.5
    if word in {"cycle", "cycles"}:
        return 0.35
    if word in {"nearby", "covered", "embraced", "central", "width"}:
        return 0.65
    if word in {"wrap", "wrapped", "wrapping", "wraps"}:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, previous, current = carry or (doc, "", "")
    if doc != old_doc:
        previous, current = "", ""

    token = prefix.token_strings[-1]
    surface = token.strip()

