    chinese = {
        "周": 1.05, "一周": 1.25, "回": 0.6, "球": 0.65, "涵盖": 0.45,
    }
    if surface in chinese:
        return (doc, "", ""), float(chinese[surface])
    if surface == "©":
        return (doc, "", ""), 0.8

    # Join English subword pieces so “circum” + “circle” is read as a word.
    match = re.search(r"([A-Za-z]+)[^A-Za-z]*$", token.lstrip())
    if match is None:
        return (doc, "", ""), 0.0
    fragment = match.group(1).lower()
    starts_word = token[:1].isspace() or not token.lstrip()[:1].isalnum()
    if current and not starts_word:
        word = current + fragment
        prior = previous
    else:
        prior, word = current, fragment

    value = _meaning(word)
    # “the” immediately after “around” or “round” also has a small response.
    if word == "the" and prior == "around":
        value = 0.72
    elif word == "the" and (prior == "round" or prior.endswith("-round")):
        value = 0.36
    # “of” in an explicit boundary phrase, rather than every occurrence.
    elif word == "of" and prior in {"surface", "outside"}:
        value = 0.5

    return (doc, prior, word), float(value)

