        if '\n' in token and capitalized:
            if lower == 'introduction':
                return -2.25 if before.isupper() else -1.80
            if lower in OPENINGS or lower in {
                    'references', 'question', 'solution', 'example'}:
                return -0.85
        if numbered:
            scale = 1.0 if capitalized else 0.22
            if word.isdigit() and previous[-1:].isspace():
                scale *= 0.45
            return numbered * scale
        return -0.01 if token == ' ' else 0.0

    if token.count(':') + token.count('：') != 1:
        return -0.025 if '::' in token else 0.0
    left, right = re.split('[:：]', token)
    if any(c.isalnum() for c in left + right):
        return 0.0
    suffix = right.strip()
    if suffix and suffix != '\\':
        return 0.08 if suffix.startswith(('"', "'", '{', '[')) else 0.0
    if capitalized and not left.strip():
        if lower == 'explanation':
            return -2.25
        if lower in STRONG_LABELS:
            return -1.10
        if lower in DESCRIPTIVE_LABELS:
            return -0.80
        if lower in OTHER_LABELS:
            return -0.60
        if lower == 'answer':
            return -0.45
        if lower in {'title', 'conclusion'}:
            return -0.30
        if before.endswith(('Error', 'Warning')):
            return 0.0 if before in {'Error', 'Warning'} else -0.35
    if not left.strip():
        if lower in {'note', 'hint', 'usage', 'warning'} and not capitalized:
            return 0.15
        if lower in {'title', 'description'} and not capitalized:
            if previous.rsplit('\n', 1)[-1].strip() == before:
                return -0.50 if lower == 'title' else -0.10
    numbered_match = NUMBER_END.search(previous)
    if numbered_match and not left.strip():
        label = numbered_match[1]
        if label[:1].isupper() and label.lower() in {'step', 'scenario'}:
            return -0.40

    if suffix == '\\':
        return 0.35
    newlines = token.count('\n')
    if '：' in token:
        return 1.29 if position == 0 else 0.27 if newlines else 0.40
    if newlines:
        if position == 0:
            return 1.10
        if newlines >= 2:
            return max(0.05, 0.51 - 0.10 * (newlines - 2))
        return 0.08 if ')' in left else 0.34
    if '"' in left or "'" in left:
        return 0.74 if position == 0 else 0.20 if lower == 'name' else 0.55
    if left.startswith(' '):
        return 0.64 if position == 0 else 0.29
    if '*' in left:
        return 0.28
    if left in {'(', '['}:
        return 0.08
    if position == 0:
        return 1.92 if not left else 1.03
    if ')' in left:
        return 1.31 - 0.09 * math.log1p(position)
    if ']' in left or '}' in left:
        return 0.61

    value = 1.07 - 0.09 * math.log1p(position)
    value += 0.36 if before.islower() else 0.12 if before.istitle() else 0.0
    value -= 0.28 if lower in CODE_WORDS else 0.0
    value -= 0.23 if lower in FIELD_NAMES else 0.0
    value -= 0.35 if FILE_END.search(previous) else 0.0
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, position = '', 0
    else:
        previous, position = carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, position)
    carry = (document, (previous + token)[-48:], position + 1)
    return carry, float(value)

programs.luna:
"""A colon pulse, plus a small negative signal on two article section headings."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if ":" in token or "：" in token:
        return None, 0.53

    if token.lower() in {"background", "introduction", "roduction"}:
        doc = prefix.document_ids[-1]
        start = len(prefix.document_ids) - 1
        while start and prefix.document_ids[start - 1] == doc:
            start -= 1
        text = "".join(prefix.token_strings[start:])
        line = text.rsplit("\n", 1)[-1].strip().upper()
        if line in {"BACKGROUND", "INTRODUCTION", "I. INTRODUCTION"}:
            return None, -2.0

    return None, 0.0

programs.haiku:
"""Fires on words about whether something meets its expected or correct behaviour:
"expected", "should", "correctly", "properly", "works", "work", "successfully", "correct", ...
Each word gets the strength it typically has in the training data. The verb "work" is
stronger after a modal or negation ("should work", "not work").
"""

STRENGTH = {
    "correctly": 1.1, "properly": 0.8, "expected": 0.73, "expect": 0.64, "expects": 0.44,
    "should": 0.4, "works": 0.48, "work": 0.32, "working": 0.35, "worked": 0.18,
    "successfully": 0.46, "correct": 0.29, "incorrect": 0.25, "wrong": 0.17,
    "desired": 0.27, "behavior": 0.28, "behaviour": 0.16, "actual": 0.12,
}
VERBS = {"work", "works", "working", "worked"}
MODALS = {"should", "not", "would", "must", "can", "will", "still"}

READS = ()

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    s = STRENGTH.get(word, 0.0)
    if word in VERBS and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in MODALS:
            s = 0.8
    return None, s

programs.luna:
"""Recognize words about things working as expected or correctly."""
READS = ()

CORE_WORDS = {
    "expect", "expected", "should", "work", "working", "correctly",
    "successfully", "unexpected", "behavior", "работает", "動作",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    for char in prefix.token_strings[-1].lower():
        word = word + char if char.isalnum() else ""
    value = 0.60 if word in CORE_WORDS else -0.003
    return (doc, word), float(value)

programs.sol:
"""A grammatical nominalization detector, strongest in Japanese.

Fact/thing, explanatory clauses, reason/purpose, manner and time receive
large positive values. Conditions, quotations and auxiliaries receive
smaller ones; ordinary case markers are negative. Chinese and Korean
nominal expressions have analogous rules. Unrecognized tokens are near
zero. These rules approximate the strong linguistic responses, not the
component's many small, idiosyncratic lexical activations.
"""
import re

READS = ()
PREDICATE_ENDS = ('る', 'う', 'く', 'ぐ', 'す', 'つ', 'ぶ', 'む',
                  'た', 'い', 'ます', 'ません', 'です', 'ない')
VOLITIONAL_STEMS = frozenset('えけげせぜてでねへべめれきぎしじちにひびぴみり')


def response(s, prev):
    predicate = prev.endswith(PREDICATE_ENDS)
    if s in {'時', '时', '際', '時に', '時の', '时候', '時候'}:
        return 0.53
    if s in {'的时候', '的時候', '際に', '時は'} or s.startswith('とき'):
        return 0.83
    if '場合' in s:
        return 1.17 if s.endswith(('は', 'には')) else 0.72
    if any('ぁ' <= c <= 'ゖ' for c in s):
        if s in {'を', 'に', 'お', 'ご', 'へ'}:
            return -0.22
        if s in {'で', 'が'}:
            return 0.15 if s == 'が' and predicate else -0.15
        if s in {'の', 'は', 'も', 'と', 'か'}:
            return 0.30 if s in {'の', 'と', 'か'} and predicate else -0.02
        if s.startswith(('のこと', 'のため', 'そのため', 'のよう')):
            return 0.22
        nominal = s.startswith(('ところ', 'わけ', 'はず', 'つもり', 'べき'))
        if 'こと' in s or nominal:
            return 0.98
        if 'もの' in s:
            marked = s.endswith(('ものが', 'ものは', 'ものを'))
            return 0.99 if marked else 0.59
        if re.search(r'の(?:は|が|も|か|に|です|だ|では)', s):
            return 0.88 if s.startswith('なの') else 1.16
        if 'ため' in s or 'ので' in s:
            return 0.58 if s.startswith('なので') else 0.93
        if 'よう' in s:
            volitional = s == 'よう' and prev and prev[-1] in VOLITIONAL_STEMS
            return 0.18 if volitional or s in {'しよう', 'みよう'} else 1.00
        if s.startswith(('ほう', 'かもしれ', 'かどうか')) or s == 'かも':
            return 1.00
        if s.startswith(('んです', 'と思')):
            return 0.82
        listing = s.startswith(('など', 'うち'))
        conditional = s.endswith(('れば', 'たら', 'なら', 'ると'))
        alternating = s.endswith('たり') and bool(re.fullmatch('[ぁ-ゖ]+', s))
        if listing or conditional or alternating:
            return 0.60
        modal = ('けど', 'けれど', 'でしょう', 'だろう', 'らしい', 'みたい')
        if s.endswith(modal):
            return 0.70
        auxiliary = ('ている', 'ていた', 'ています', 'ております', 'てしまう')
        if s.endswith(auxiliary):
            return 0.43
        if s in {'という', 'とは', 'だと', 'とか', 'だけ', 'まま', 'ですね', 'よね'}:
            return 0.48
        return 0.01 if len(s) == 1 else 0.08
    if s in {'的是', '的话', '的話'}:
        return 0.54
    if s in {'了', '呀', '嘛', '啊', '吧', '哦', '吗', '嗎',
             '者', '所', '事', '話', '东西', '東西', '地方'}:
        return 0.25
    if any('가' <= c <= '힣' for c in s):
        if s.startswith(('것', '경우')):
            return 1.02
        if s in {'을', '를', '이', '에', '그', '가', '은', '의', '로', '에서'}:
            return -0.19
        if s.endswith(('다면', '는데', '겠다', '도록')):
            return 0.64
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1].strip()
    return (doc, s), float(response(s, prev))

programs.luna:
"""Approximate a sparse response to Japanese clause grammar.

It gives positive values to Japanese nominalizers, clause connectives, and
inflected endings, and negative values to four standalone case particles. A few
other Japanese particles and Chinese time, relation, aspect, and sentence-ending
words receive smaller values.
"""

READS = ()

JAPANESE_CLAUSE_MARKERS = (
    "場合", "ため", "こと", "のに", "よう", "のは", "のが", "のも",
    "のか", "には", "にも", "ので", "との", "という", "てしまう",
    "らしい", "だろう", "ばかり", "として", "といった", "である",
    "ではない", "ではなく", "と思", "ています", "しています",
    "ている", "ていた", "しました", "だった", "でした", "ません",
    "でき", "やすい", "れば", "とき", "際", "時", "うち", "など",
    "ほうが", "んですよね", "と考え",
)

JAPANESE_CASE_PARTICLES = {"を", "に", "で", "が"}

JAPANESE_MINOR_PARTICLES = {"と", "の", "から"}

CHINESE_CLAUSE_WORDS = {"时", "時", "时候", "時候", "后", "後", "那些", "只有", "之中"}


def step(carry, prefix, upstream):
    """Give modest positive scores to common temporal and clause-linking words."""
    word = prefix.token_strings[-1].strip()
    if word in JAPANESE_CASE_PARTICLES:
        return None, -0.22
    if any(marker in word for marker in JAPANESE_CLAUSE_MARKERS):
        return None, 0.62
    if word in JAPANESE_MINOR_PARTICLES:
        return None, {"と": 0.13, "の": 0.06, "から": 0.08}[word]
    if word in CHINESE_CLAUSE_WORDS:
        return None, 0.45
    if word == "了":
        return None, 0.18
    if word == "這":
        return None, 0.14
    if word == "那":
        return None, -0.10
    if word in {"呀", "哦", "嘛"}:
        return None, 0.30
    return None, 0.0

programs.sol:
"""Predict a negative response to short 'ir' and 'air' spelling chunks.

An isolated 'ir', or a consonant followed by 'ir', gives a large response.
Longer chunks and a following vowel usually weaken it. A few common words
are exceptions, as are direction/directory versus direct. Cyrillic, Arabic
and Turkish spellings of a similar vowel-r sequence are also recognized.

Only the current token is used. The numbers summarize training responses;
this does not reconstruct attention or infer a word's meaning.
"""
READS = ()

def response(token):
    word = token.strip().strip('_./-()[]{}:').lower()
    # Frequent whole-word spellings do not behave like isolated fragments.
    if word.startswith(('first', 'third', 'thirt', 'their', 'pair', 'repair')):
        return 0.0
    if 'ir' in word:
        before, after = word.split('ir', 1)
        if before == 'd' and after.startswith('ect'):
            return -0.9 if after.startswith(('ection', 'ectory')) else 0.0
        # A fragment ending at r retains the strongest response.
        if not after:
            if not before:
                value = -4.4
            elif before == 'a':
                value = -3.0 if token.startswith(' ') else -2.3
            elif len(before) <= 1 or before in ('ch', 'sh'):
                value = -4.0
                if before in ('p', 't'):
                    value = -3.0
                elif before == 'w':
                    value = -1.9
                elif before == 'd' and token != 'dir' and token != 'DIR':
                    value = -2.6
                elif before in ('o', 'u'):
                    value = -1.6
            else:
                value = -2.8 / len(before)
                if before.endswith('a'):
                    value = -0.9 / (len(before) - 1)
                elif before.endswith('o'):
                    value = -0.4 / (len(before) - 1)
        else:
            # Letters following r generally signal a more complete word.
            if after.startswith('e'):
                value = -0.85
                if len(before) == 1:
                    return -0.7 / (1 + 0.1 * (len(after) - 1))
            elif after[0] in 'aiou':
                value = -1.6
            else:
                value = -3.2
                if after.startswith('th'):
                    value = -0.6
                elif before in ('g', 'w'):
                    value = -0.8
                elif after.startswith('m'):
                    value = -1.8
            value /= 1.0 + 0.55 * max(0, len(after) - 1)
            if before:
                value /= 1.0 + 1.0 * len(before)
        return value
    for spelling, strength in (('ир', -3.3), ('یر', -2.9),
                               ('ير', -1.8), ('ır', -2.1)):
        if word.startswith(spelling):
            return strength / (1.0 + 0.6 * max(0, len(word) - 2))
    return 0.0

def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

"""Short horizontal separators, with a distinction between prose and arithmetic.

The main positive responses are en dashes, tildes, and isolated hyphens.
A hyphen after a word or shell command is stronger than one after a variable,
equals sign, or newline. Chinese, Japanese and Korean context boosts several
separators. An em dash or doubled ASCII hyphen is not an en dash.
Other tokens are approximated as zero, omitting word-specific small offsets.
"""
import re

READS = ()
SHELL_COMMANDS = {
    'cat', 'grep', 'ls', 'sed', 'find', 'git', 'python', 'python3',
    'pip', 'curl', 'wget', 'echo', 'sort', 'diff', 'chmod', 'rm', 'rg',
}
HYPHENATED_PREFIXES = {'non', 'pre', 'anti', 'mid', 're'}
FUNCTION_WORDS = {'and', 'are', 'is', 'between', 'from', 'than', 'that', 'the'}


def response(token, previous, tail):
    s, c = token.strip(), previous[-1:]
    spaced = token.startswith(' ')
    han = bool(c and '\u3400' <= c <= '\u9fff')
    kana = bool(c and '\u3040' <= c <= '\u30ff')
    korean = bool(c and '\uac00' <= c <= '\ud7af')
    cyrillic = bool(c and '\u0400' <= c <= '\u052f')
    math = bool(re.search(r'[=\\^_$]', tail[-60:]))
    word = previous.strip()

    if s == '-':
        if token.endswith('\n'):
            return 0.8 if han else (0.2 if c.isspace() else 0.06)
        if han or kana or korean:
            return 1.56 if han else (0.75 if kana else 1.10)
        if not previous:
            return -0.20
        if spaced:
            if cyrillic:
                return 0.58
            if word in SHELL_COMMANDS:
                return 0.68
            if c == '-' or previous.endswith(' +'):
                return -0.18
            if c in '=([{<+':
                return 0.0
            if c.isspace() or c in ',:':
                return 0.18
            if c.isdigit():
                return 0.10 if math else 0.26
            if c.isalpha():
                if len(word) <= 2 or word in FUNCTION_WORDS:
                    return 0.09 if math else 0.23
                return 0.44 if math else 0.54
            return 0.20 if math else 0.40
        if c.isspace():
            return -0.10 if previous.rstrip().endswith(':') else 0.0
        if cyrillic:
            return 0.35
        if c == '=':
            return -0.22
        if c.isdigit():
            return 0.10
        if c.isalpha():
            if word in HYPHENATED_PREFIXES:
                return -0.10
            return 0.03 if math or len(word) <= 2 else 0.22
        return 0.06

    if s == '–':
        if han or kana or korean:
            return 1.40 if spaced else 1.85
        return (0.48 if math else 0.71) if spaced else 0.55
    if s and set(s) == {'—'}:
        return (0.94 if len(s) > 1 else 1.40) if han else 0.0
    if s and set(s) <= {'~', '～', '〜'} and len(s) <= 2:
        if token.endswith('\n'):
            return 0.79 if han else 0.25
        if han:
            return 1.70 if s == '~' else 1.40
        return 0.61 if spaced or len(s) == 2 else (0.49 if s == '~' else 0.86)
    if s in {'・', '·'}:
        if s == '・':
            return 0.49 if han else (0.33 if kana else 0.20)
        return (0.25 if spaced else 0.79) if han else -0.05
    if s in {'+', '/', '|', '／'}:
        if han or kana:
            return {'+': 1.0, '/': 0.49, '|': 0.54, '／': 0.62}[s] if han else 0.30
        return -0.06 if (s == '+' and not spaced) or c.isdigit() else 0.0
    if s.endswith('-') and not any(ch.isalnum() for ch in s):
        if s.count('-') > 1:
            return 0.9 if han else (-0.05 if len(s) == 2 else 0.0)
        if '|' in s or '%' in s:
            return 0.80
        if '[' in s:
            return 0.54 if spaced else 0.66
        if (spaced and '(' in s) or ')' in s or '}' in s:
            return 0.20
        return 0.38
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (doc, token, (tail + token)[-100:]), float(value)
